window.__LEX={"G600":"<h1>apokathistemi</h1>\n<p>Strong n° 600 <i>Prononciation [ap-ok-ath-is'-tay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>restaurer à l'état initial</li>\n<li>être guéri, revenir à son état initial, rétablir quelqu'un dans ses forces</li>\n<li>restituer, rendre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·καθίστημι :<br>   I</b> <i>tr. aux temps suiv. : (prés., impf., f</i>. -καταστήσω, <i>ao.1</i> -κατέστησα) :<br><b>      1</b> remettre en l’état antérieur, rétablir : πολιτείαν, DÉM. <i>256, 3 (décr.) ou</i> πολίτευμα, POL. <i>9, 36, 4,</i> rétablir un gouvernement ; τινα εἰς οἶκον, POL. <i>8, 29, 6,</i> rétablir qqn dans ses foyers ; πολίτας, PLUT. <i>Alex. 7,</i> rétablir des citoyens dans leur situation ;<br><b>      2</b> <i>p. suite,</i> restituer, rendre : τοὺς ὁμήρους, POL. <i>3, 98, 7,</i> les otages ;<br><b>      3</b> tendre (un cordon) HÉRON <i>Aut. 267, etc. ;</i><br><b>   II</b> <i>intr. aux temps suiv. (ao.2</i> -κατέστην, <i>pf</i>. -καθέστηκα, <i>et au moy</i>.) :<br><b>      1</b> se rétablir : εἰς τὴν ἐξ ἀρχῆς κατάστασιν, POL. <i>25, 1, 1,</i> en revenir à la constitution primitive ; <i>t. de méc</i>. ἀποκαθίστασθαι, revenir à sa position primitive, <i>en parl. de ressorts métalliques,</i> PHIL. BYZ. ; <i>abs</i>. revenir à l’état primitif, HPC. <i>1222</i> h, <i>etc. ;</i><br><b>      2</b> se reposer, se calmer, cesser, <i>en parl. de maladies,</i> HPC. <i>1258</i> f ; <i>de mouvement,</i> PLUT. <i>M. 564</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Pf</i>. ἀποκαθέστακα <i>au sens trans</i>. POL. <i>21, 9</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-καθιστεμι - ἀποκαθίστημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (3)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G601":"<h1>apokalupto</h1>\n<p>Strong n° 601 <i>Prononciation [ap-ok-al-oop'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>découvrir, dévoiler ce qui est voilé ou couvert\n<ol type=\"a\">\n<li>révéler, mettre à nu</li>\n</ol>\n</li>\n<li>porter à la connaissance, rendre manifeste</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·καλύπτω</b> <span>[κᾰ]</span><br><b>      1</b> découvrir (la tête, la poitrine, <i>etc</i>.) HDT. <i>1, 119 ;</i> PLAT. <i>Prot. 352</i> a, <i>etc. ; au pass</i>. ARSTT. <i>H.A. 9, 47 ; fig. en parl. de pers</i>. ἀπ. τινά, dévoiler <i>ou</i> démasquer qqn, <i>càd</i>. le forcer à parler, LUC. <i>V. auct. 23 ; ou</i> le faire connaître dans tout son jour, LUC. <i>Cat. 26 ; en mauv. part :</i> ἀποκεκαλυμμένοι λόγοι, Ps.-PLUT. <i>V. Hom. 214,</i> discours indécents ;<br><b>      2</b> <i>fig</i>. révéler, PLAT. <i>Prot. 352</i> b, <i>etc. ;</i><br><b><i>Moy.</i></b> :<br><b>   I <i>tr.</i></b> découvrir (une partie de son corps) : τὴν κεφαλήν, PLUT. <i>Crass. 6,</i> se découvrir la tête ;<br><b>   II <i>intr</i>.<br>      1</b> se dévoiler, <i>càd</i>. montrer ses dispositions <i>ou</i> son caractère au grand jour, PLUT. <i>M. 880</i> e ; SPT. <i>1Reg. 2, 29 ; 3, 21 ;</i> ἀπ. πρός τινα, PLUT. <i>Alex. 55,</i> montrer sa mauvaise humeur contre qqn ;<br><b>      2</b> agir ouvertement : πρός τι, DS. <i>17, 62, etc</i>. en vue de qqe ch., <i>càd</i>. se préparer <i>ou</i> aspirer ouvertement à qqe ch.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-καλυπτω - ἀποκαλύπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td>Comparer : , \n<br><br> est sensé décrire une manifestation externe, dont le sens par là même est ouvert à tous, en particulier ou isolé;\n<br><br> est une révélation interne, et durable, à la pensée du croyant. Le  ou « dévoilement » précède et produit le  ou « manifestation » ; le premier s'attache à l'objet révélé, le second à la personne à qui la révélation est faite.\n<br><br>Comparer : , \n<br><br> – évident, ce qui est connu et compris\n<br><br> – manifeste, en opposition à ce qui est caché et invisible\n<br><br> désigne plutôt une perception intérieure,  s'appuie sur l'apparence externe.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n26 fois dans 26 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Luc (5)</li>\n<li>Jean (1)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (3)</li>\n<li>Galates (2)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n<li>2 Thessaloniciens (3)</li>\n<li>1 Pierre (3)</li>\n</ul>\n</td></tr>\n</table>","G602":"<h1>apokalupsis</h1>\n<p>Strong n° 602 <i>Prononciation [ap-ok-al'-oop-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre à nu</li>\n<li>révélation d'une vérité, instruction\n<ol type=\"a\">\n<li>concernant les choses inconnues auparavant</li>\n<li>usage d'événements par lequel les choses ou la nature de certains, jusqu'ici cachées deviennent visibles à tous</li>\n</ol>\n</li>\n<li>manifestation, apparence</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀποκάλυψις, εως (ἡ)</b> <span>[κᾰ]</span><br>\n<b>      1</b> action de découvrir, PHILOD. <i>De sup. 23 ;</i><br>\n<b>      2</b> <i>fig</i>. révélation, PLUT. <i>M. 70</i> f ; <br><i>particul</i>. révélation divine, NT. <i>2Cor. 12, 1, etc. ; d’où</i> l’Apocalypse, <i>titre de divers ouvrages parmi les Livres saints,</i> CLÉM. <i>1, 525 ; 2, 338, etc</i>.<br><span><b>Étym</b>. ἀποκαλύπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αποκαλυψις - ἀποκάλυψις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n18 fois dans 18 versets de 9 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (2)</li>\n<li>Ephésiens (2)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Pierre (3)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G603":"<h1>apokaradokia</h1>\n<p>Strong n° 603 <i>Prononciation [ap-ok-ar-ad-ok-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ferme espoir et attente dans l'anxiété, attente impatiente (exactement en tendant la tête pour épier)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀποκαραδοκία, ας (ἡ)</b> <span>[κᾰᾱ]</span> attente impatiente, NT. <i>Rom. 8, 19</i>.<br><span><b>Étym</b>. <i>v</i>. ἀποκαραδοκέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-καραδοκια - ἀποκαραδοκία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G604":"<h1>apokatallasso</h1>\n<p>Strong n° 604 <i>Prononciation [ap-ok-at-al-las'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>réconcilier complètement</li>\n<li>se réconcilier, revenir à un état d'harmonie comme dans le passé</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·καταλλάσσω</b>, <i>att</i>. <b>-άττω</b>, réconcilier complètement, NT. <i>Eph. 2, 16 ; Col. 1, 20</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αποκαταλλασσω - ἀποκαταλλάσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>Colossiens (2)</li>\n</ul>\n</td></tr>\n</table>","G605":"<h1>apokatastasis</h1>\n<p>Strong n° 605 <i>Prononciation [ap-ok-at-as'-tas-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>restauration\n<ol type=\"a\">\n<li>d'une vraie théocratie</li>\n<li>de l'état parfait d'avant la chute</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀποκατάστασις, εως (ἡ)</b> <span>[ᾰσ]</span><br><b>   I</b> rétablissement d’une chose <i>ou</i> d’une personne en son état antérieur, restauration, ARSTT. <i>M. mor. 2, 7, 12, etc. ;</i> POL. <i>3, 99, 6 ; 4, 23, 1, etc. ;</i> DH. <i>10, 8, etc. ;</i><br><b>   II</b> <i>particul. :</i><br><b>      1</b> rétablissement d’une personne malade, ARÉT. <i>9, 22 ;</i><br><b>      2</b> retour d’une saison, PLUT. <i>M. 937</i> f ;<br><b>      3</b> retour périodique (d’un astre) PLAT. <i>Ax. 370</i> b.<br><span><b>Étym</b>. ἀποκαθίστημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-καταστασις - ἀποκατάστασις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G606":"<h1>apokeimai</h1>\n<p>Strong n° 606 <i>Prononciation [ap-ok'-i-mahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être posé de côté, réservé, gardé</li>\n<li>se réserver pour quelqu'un, l'attendre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπό·κειμαι :<br>   I</b> être placé loin de, PD. <i>N. 11, 46 ;</i> ARAT. <i>110 ;</i><br><b>   II</b> être mis de côté, <i>d’où :</i><br><b>      1</b> être mis en réserve, XÉN. <i>An. 2, 3, 15 ; 5, 4, 27, etc. ;</i> παρά τινι, LYS. <i>153, 45,</i> auprès de qqn, chez qqn ; <i>fig</i>. ἐν οἷς γὰρ χάρις ἡ χθονία ξύν' ἀπόκειται πενθεῖν οὐ χρή, SOPH. <i>O.C. 1752,</i> car il ne faut pas qu’ils s’affligent ceux à qui le pays tout entier réserve sa faveur ; <i>avec le dat</i>. οὐκ ἔστιν οὖν τούτοις δίκαιος ἀποκείμενος ἔλεος, DS. <i>13, 31,</i> il n’est donc pas juste qu’on leur réserve de la pitié ;<br><b>      2</b> être laissé à l’écart, être méprisé <i>ou</i> délaissé, CRAT. (SUID.) ; DS. <i>3, 46 ;</i> PLUT. <i>M. 159</i> f.<br><span><b><span class=\"arrow\"></span></b> <i>En ces divers sens</i> ἀπόκειμαι <i>équivaut au pass. de</i> ἀποτίθημι.<br><span><b>Étym</b>. ἀπό, κεῖμαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-κειμαι - ἀπόκειμαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Colossiens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G607":"<h1>apokephalizo</h1>\n<p>Strong n° 607 <i>Prononciation [ap-ok-ef-al-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>couper la tête, décapiter</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·κεφαλίζω</b> <span>[φᾰ]</span> décapiter, ARR. <i>Epict. 1, 1, 24 ;</i> ARTÉM. <i>1, 35 ;</i> SPT. <i>Ps. 101, 7, etc</i>.<br><span><b>Étym</b>. ἀπό, κεφαλή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-κεφαλιζω - ἀποκεφαλίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G608":"<h1>apokleio</h1>\n<p>Strong n° 608 <i>Prononciation [ap-ok-li'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>fermer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·κλείω :<br>   I</b> intercepter, fermer : τὰς πύλας, HDT. <i>1, 150, etc</i>. les portes ; τὴν ὄψιν, HDT. <i>4, 7,</i> intercepter la vue ; τὴν πόλιν, AR. <i>Lys. 487,</i> fermer les portes de la ville ; <i>avec un acc. de pers</i>. ἀπ. τινὰ ἔνδον, DÉM. <i>1359, 6,</i> enfermer qqn ; ἀπ. τὴν βλάστην τοῦ πτεροῦ, PLAT. <i>Phæd. 251</i> d, empêcher la croissance de l’aile ; <i>au pass</i>. ἀποκεκλεῖσθαι τοῦ σίτου, τῶν σιτίων, HPC. <i>532, 20 ; 373, 46 ;</i> DÉM. <i>1260, 31,</i> avoir de l’éloignement pour la nourriture, n’avoir pas d’appétit ; <i>en parl. de pays,</i> borner, limiter, HDT. <i>7, 129 ; au pass</i>. HDT. <i>4, 100 ;</i><br><b>   II</b> exclure, <i>d’où :</i><br><b>      1</b> écarter, repousser : τινά τινος, HDT. <i>1, 37, etc. ou</i> ἀπό τινος, AR. <i>Vesp. 601,</i> exclure qqn de qqe ch., interdire à qqn l’accès <i>ou</i> la participation à qqe ch. ; ἀπ. τινὰ μή <i>avec l’inf</i>. AR. <i>Av. 1263,</i> interdire à qqn de, <i>etc. ;</i><br><b>      2</b> <i>abs</i>. faire une exception, DÉM. <i>841, 5 ;</i><br><b><i>Moy.</i></b> intercepter : τινὰ τῆς διαϐάσεως, THC. <i>6, 101,</i> barrer le passage à qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἀποκληΐω, <i>d’où prés. part</i>. ἀποκληΐοντα, HDT. <i>4, 7 ; ao. 3 sg</i>. ἀπεκλήϊσε, HDT. <i>5, 104 ; part</i>. ἀποκληΐσας, HDT. <i>1, 37, etc. ; pass. prés. 3 sg</i>. ἀποκληΐεται, HDT. <i>4, 100 ; ao. ind. 3 pl</i>. ἀπεκληΐσθησαν, HDT. <i>3, 58 ; sbj. 3 sg</i>. ἀποκληϊσθῇ, HDT. <i>1, 165 ; part</i>. ἀποκληϊσθέντες, HDT. <i>3, 55. — Att</i>. ἀποκλῄω, AR. <i>Eccl. 420 ;</i> XÉN. <i>Mem. 3, 11, 10 ; fut</i>. ἀποκλῄσω, AR. <i>Vesp. 775 ;</i> ἀποκλῄσειν, THC. <i>6, 64 ; ao</i>. ἀπέκλῃσα, ESCHL. <i>Pr. 670 ;</i> SOPH. <i>O.R. 1388 ; pf</i>. ἀποκέκλῃκα, AR. <i>Av. 1263 ; pass. prés</i>. ἀποκλῄομαι, THC. <i>2, 76 ; pf. part</i>. ἀποκεκλῃμένοι, THC. <i>4, 34, etc. — Dor</i>. ἀποκλᾴω, <i>d’où ao. impér</i>. ἀπόκλᾳξον, THCR. <i>Idyl. 15, 43 ; part</i>. ἀποκλᾴξας, THCR. <i>Idyl. 15, 77</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-κλειω - ἀποκλείω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G609":"<h1>apokopto</h1>\n<p>Strong n° 609 <i>Prononciation [ap-ok-op'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>couper, amputer, retrancher, mutiler, émasculer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·κόπτω</b>, détacher en coupant, couper : κάρη, IL. <i>11, 261 ;</i> αὐχένα, IL. <i>11, 146 ;</i> χεῖρας, HDT. <i>6, 91, etc</i>. couper la tête, le cou, les mains ; γεφύραν, PLUT. <i>Nic. 26,</i> couper un pont ; <i>au pass</i>. τοὺς αὐχένας ἀποκοπῆναι, DH. <i>3, 58,</i> avoir eu le cou tranché, <i>en parl. de suppliciés ;</i> ἀποκοπεὶς χεῖρας καὶ πόδας, LIB. <i>4, 169,</i> qui a eu les mains et les pieds coupés ; <i>p. anal. ou fig</i>. ἀπ. τινὰ ἀπὸ τόπου, XÉN. <i>An. 3, 4, 39, etc</i>. couper qqn d’un lieu (un corps de troupes d’une place forte, <i>etc</i>.) ; ἀποκεκομμένης αὐτῷ τῆς φωνῆς, PLUT. <i>Dem. 25,</i> la voix s’étant arrêtée dans son gosier ; ἀποκοπῆναι τῆς ἐλπίδος, PLUT. <i>Pyrrh. 2,</i> voir son espérance brisée ; ἀποκόπτειν τῆς γνώμης τὸ ἀμφίϐολον, ALCIPHR. <i>1, 8,</i> couper court aux hésitations de l’esprit ; <i>t. de gr</i>. ἀποκόπτεσθαι, EUST. <i>Il. p. 487, 10 ;</i> EM. <i>609, 54,</i> être apocopé (<i>v</i>. ἀποκοπή) ;<br><b><i>Moy.</i></b> se frapper (en signe de deuil) : ἀπ. νεκρόν, EUR. <i>Tr. 623,</i> se frapper en pleurant un mort.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αποκοπτω - ἀποκόπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>Jean (2)</li>\n<li>Actes (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G610":"<h1>apokrima</h1>\n<p>Strong n° 610 <i>Prononciation [ap-ok'-ree-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un arrêt, une sentence, une réponse, décision judiciaire,\n<ol type=\"a\">\n<li>Dans <a class=\"ref\" data-r=\"2CO1.9\">2 Corinthiens 1.9</a> le sens est : « me demandant si je peux être sauvé, je réponds : je dois mourir »</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπόκριμα, ατος (τὸ)</b> <span>[ῐ]</span><br><b>      1</b> réponse, POL. <i>Exc. Vat. 12, 26</i> b, <i>1 ;</i><br><b>      2</b> sentence judiciaire, condamnation, NT. <i>2Cor. 1, 9</i>.<br><span><b>Étym</b>. ἀποκρίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-κριμα - ἀπόκριμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G611":"<h1>apokrinomai</h1>\n<p>Strong n° 611 <i>Prononciation [ap-ok-ree'-nom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>donner une réponse à une question donnée, répondre</li>\n<li>commencer à parler, mais toujours si quelque chose a précédé (dit ou fait) et la remarque s'y réfère</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-κρινομαι - ἀποκρίνομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n249 fois dans 247 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (55)</li>\n<li>Marc (44)</li>\n<li>Luc (49)</li>\n<li>Jean (78)</li>\n<li>Actes (21)</li>\n<li>Colossiens (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G612":"<h1>apokrisis</h1>\n<p>Strong n° 612 <i>Prononciation [ap-ok'-ree-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une réplique, une réponse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπόκρισις, εως (ἡ)</b> <span>[ῐσ]</span><br><b>      1</b> tri, choix, PLAT. <i>Def. 415</i> d ; <i>t. de méd</i>. sécrétion, HPC. <i>376, 28 et 52 ; 377, 24, etc. ;</i><br><b>      2</b> réponse, THGN. <i>1167 ;</i> HDT. <i>1, 49, etc. ;</i> THC. <i>3, 60 ;</i> XÉN. <i>Hell. 6, 1, 17, etc</i>.<br><span><b>Étym</b>. ἀποκρίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-κρισις - ἀπόκρισις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G613":"<h1>apokrupto</h1>\n<p>Strong n° 613 <i>Prononciation [ap-ok-roop'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>cacher, enfouir, ensevelir</li>\n<li>dissimuler, garder secret</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·κρύπτω</b> <span>(<i>f</i>. ύψω, <i>ao</i>. ἀπέκρυψα)</span><br><b>   I</b> cacher, <i>d’où :</i><br><b>      1</b> mettre en lieu sûr, soustraire : τινί τι, IL. <i>11, 717,</i> qqe ch. à qqn ; τινὰ θανάτοιο νόσφιν ἀ. IL. <i>18, 465,</i> soustraire qqn à la mort ;<br><b>      2</b> cacher, couvrir : τὸν ἥλιον ὑπὸ τοῦ πλήθεος τῶν ὀϊστῶν, HDT. <i>7, 226,</i> cacher le soleil sous la multitude des traits ; χιὼν ἀπέκρυψε τὰ ὅπλα, XÉN. <i>An. 4, 4, 11,</i> la neige couvrit les armes ; <i>p. ext</i>. mettre dans l’ombre, obscurcir, EUR. <i>fr. 152 ; fig</i>. PLAT. <i>Ap. 22</i> d ; <i>au pass</i>. disparaître, s’éclipser, HÉRON <i>Aut. 265 ;</i><br><b>      3</b> cacher, dissimuler : τινά τι, HDT. <i>7, 28 ;</i> τι ἀπό τινος, SPT. <i>Jer. 32, 17 ; cf. 2Reg. 4, 27,</i> qqe ch. à qqn ;<br><b>   II</b> perdre de vue : γῆν, PLAT. <i>Prot. 338</i> a, la terre, <i>en parl. de navigateurs ;</i> τινά, LUC. <i>V.H. 2, 38,</i> arriver hors de la vue de qqn ; <i>cf</i>. THC. <i>5, 65 ;</i><br><b><i>Moy.</i></b> cacher, dissimuler : τι, XÉN. <i>Œc. 15, 11, etc. ;</i> PLAT. <i>Gorg. 492</i> a, <i>etc</i>. qqe ch. ; τινά τι, XÉN. <i>Œc. 15, 11 ;</i> PLAT. <i>Ap. 24</i> a, <i>etc</i>. qqe ch. à qqn ; ἀ. μὴ ποιεῖν, THC. <i>2, 53,</i> dissimuler qu’on fait, <i>etc. ;</i> πρός τινα ἀποκρύψασθαι, ISOCR. <i>221 ; cf</i>. ISOCR. <i>443 ;</i> DH. <i>11, 33 ; rar. avec l’acc. seul :</i> τινὰ ἀποκρύπτεσθαι, XÉN. <i>Cyr. 8, 7, 23,</i> se cacher de qqn ; <i>avec un part</i>. ἀπεκρυπτόμην ὑμᾶς ἔχων πολλὰ καὶ σοφὰ λέγειν, XÉN. <i>Conv. 1, 6,</i> je vous cachais que j’avais beaucoup de choses avisées à vous dire.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. itér. 3 sg</i>. ἀποκρύπτασκε, HÉS. <i>Th. 157. Ao.2 moy. 3 sg</i>. ἀπεκρύϐετο, APD. <i>3, 2, 1</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αποκρυπτω - ἀποκρύπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G614":"<h1>apokruphos</h1>\n<p>Strong n° 614 <i>Prononciation [ap-ok'-roo-fos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>caché, secret</li>\n<li>enfermé</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπόκρυφος, ος, ον</b> <span>[ῠ]</span> soustrait aux regards, caché, secret, HDT. <i>2, 35 ;</i> EUR. <i>H.f. 1070, etc. ;</i> ἀ. τινος, XÉN. <i>Conv. 8, 11,</i> caché à qqn, qui se fait à l’insu de qqn ; <i>en parl. des livres saints non canoniques,</i> apocryphe, <i>càd</i>. tenu caché, non lu dans les synagogues <i>ou</i> dans les églises, CLÉM. <i>773, 1133 ;</i> ORIG. <i>1, 65, etc. ;</i> BAS. <i>3, 649 edd. Migne etc</i>.<br><span><b>Étym</b>. ἀποκρύπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αποκρυφος - ἀπόκρυφος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G615":"<h1>apokteino</h1>\n<p>Strong n° 615 <i>Prononciation [ap-ok-ti'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tuer de n'importe quelle manière\n<ol type=\"a\">\n<li>détruire, laisser périr</li>\n</ol>\n</li>\n<li>métaph. éteindre, abolir\n<ol type=\"a\">\n<li>infliger une mort morale</li>\n<li>priver de vie spirituelle et procurer la misère éternelle</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·κτείνω</b> <span>(<i>f</i>. -κτενῶ, <i>ao</i>. ἀπέκτεινα, <i>ao.2</i> ἀπέκτανον <span>[τᾰ]</span> <i>pf.2</i> ἀπέκτονα)</span><br><b>      1</b> tuer, faire périr, IL. <i>5, 675, etc. ;</i> OD. <i>23, 121, etc. ; avec un suj. de chose (pièces de bois tombant sur qqn</i>) ESCHN. <i>88, 36 ; particul</i>. mettre à mort, exécuter, <i>en parl. du bourreau,</i> HDT. <i>6, 4 ; p. ext</i>. condamner à mort, <i>en parl. des juges,</i> ANT. <i>140, 24 ;</i> PLAT. <i>Ap. 30</i> d, <i>etc. ; en parl. de la loi,</i> PLAT. <i>Prot. 325</i> b ; <i>ou</i> demander la mort d’un accusé, <i>en parl. de l’accusateur,</i> AND. <i>34, 7 ;</i> XÉN. <i>Hell. 2, 3, 21 ;</i><br><b>      2</b> <i>fig</i>. faire mourir (de dépit, de désespoir, <i>etc</i>.), mettre à la torture, EUR. <i>Hipp. 1064, Or. 1027</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pour le pass. les Att. emploient de préférence</i> ἀποθνῄσκω ὑπό τινος (<i>v</i>. ἀποθνῄσκω). — <i>Fut. ion</i>. -κτενέω, HDT. <i>3, 30. Ao.2, 1 pl. poét</i>. ἀπέκταμεν, OD. <i>23, 121 ; inf</i>. ἀποκτάμεναι, IL. <i>20, 165 ou</i> ἀποκτάμεν, IL. <i>5, 675. Pf. réc</i>. ἀπεκτόνηκα, ARSTT. <i>Soph. el. 33, 2 ;</i> PLUT. <i>Tim. 11 ; ou</i> ἀπέκταγκα, ARSTT. <i>Pol. 7, 2 (vulg. ; mss</i>. ἀπεκτακότα) ; POL. <i>3, 86, 10 ; ou</i> ἀπέκτακα, POL. <i>11, 18. Pl.q.pf. 3 sg. ion</i>. ἀπεκτόνεε, HDT. <i>5, 67. Pass. ao</i>. ἀπεκτάνθην, DC. <i>65, 4 ; pf. inf</i>. ἀπεκτάνθαι, POL. <i>7, 7. Moy. ao.2 au sens pass. 3 sg</i>. ἀπέκτατο, IL. <i>15, 437 ; 17, 472 ; part</i>. ἀποκτάμενος, IL. <i>4, 494</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-κτεινω - ἀποκτείνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n74 fois dans 70 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (13)</li>\n<li>Marc (11)</li>\n<li>Luc (12)</li>\n<li>Jean (12)</li>\n<li>Actes (6)</li>\n<li>Romains (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Apocalypse (15)</li>\n</ul>\n</td></tr>\n</table>","G616":"<h1>apokueo</h1>\n<p>Strong n° 616 <i>Prononciation [ap-ok-oo-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>engendrer\n<ol>\n<li>vient du sein</li>\n<li>donner naissance à, mettre au monde</li>\n</ol>\n</li>\n<li>produire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·κυέω-ῶ</b>, mettre au monde, enfanter, DH. <i>1, 70 ;</i> PLUT. <i>Syll. 37 ;</i> LUC. <i>D. mar. 10, 1, etc. ; fig. en parl. du péché qui enfante la mort,</i> NT. <i>Jac. 1, 15</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-κυεω - ἀποκυέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Jacques (2)</li>\n</ul>\n</td></tr>\n</table>","G617":"<h1>apokulio</h1>\n<p>Strong n° 617 <i>Prononciation [ap-ok-oo-lee'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>rouler une pierre, l'écarter</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·κυλίω</b> <span>[ῠ]</span><br><b>      1 <i>tr.</i></b> faire rouler, SPT. <i>Gen. 29, 3 ;</i> NT. <i>Matth. 28, 2 ; Marc. 16, 3 ;</i><br><b>      2 <i>intr.</i></b> rouler, LUC. <i>Rh. præc. 3</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-κυλιω - ἀποκυλίω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G618":"<h1>apolambano</h1>\n<p>Strong n° 618 <i>Prononciation [ap-ol-am-ban'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>recevoir\n<ol type=\"a\">\n<li>ce qui est dû ou promis</li>\n</ol>\n</li>\n<li>reprendre, recouvrer\n<ol type=\"a\">\n<li>recevoir une rétribution</li>\n</ol>\n</li>\n<li>prendre aux autres, prendre à part</li>\n<li>recevoir l'hospitalité de quelqu'un</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·λαμϐάνω</b> <span>(<i>f</i>. ἀπολήψομαι, <i>ao.2</i> ἀπέλαϐον, <i>pf</i>. ἀπείληφα ; <i>ao. pass</i>. ἀπελήφθην, <i>pf</i>. ἀπείλημμαι)</span><br><b>   I</b> (ἀπό, en venant de, de) :<br><b>      1</b> prendre d’(un point déterminé), <i>d’où</i> retenir ; <i>au pass</i>. être retenu, HÉRON <i>Aut. 268 ;</i><br><b>      2</b> recevoir en échange, en retour : μισθόν, HDT. <i>8, 137 ;</i> XÉN. <i>Eq. 2, 2 ; An. 7, 7, 14,</i> un salaire ; χάριν, XÉN. <i>Mem. 4, 4, 17,</i> des témoignages de reconnaissance ; ὅρκους, DÉM. <i>59, 11, etc</i>. recevoir des serments ; λόγον παρά τινος, ESCHN. <i>37, 40,</i> se faire rendre des comptes par qqn ;<br><b>      3</b> recouvrer : χρέα, AND. <i>25, 20,</i> des dettes ; τὴν τυραννίδα, HDT. <i>1, 61 ;</i> τὴν ἡγεμονίαν, ISOCR. <i>44</i> e, la royauté, la prépondérance ;<br><b>      4</b> prendre des mains de, ôter : ἀπό τινος, POL. <i>22, 26, 8,</i> qqe ch. à qqn ;<br><b>   II</b> (ἀπό, hors de, loin de, en séparant) :<br><b>      1</b> prendre une part de, prendre par parties (<i>p. opp. à</i> prendre le tout) <i>acc</i>. PLAT. <i>Rsp. 420</i> c ;<br><b>      2</b> prendre à part : τινὰ μοῦνον, HDT. <i>1, 209 ;</i> AR. <i>Ran. 78,</i> prendre qqn seul à part ; ἀπ. κατ' ἰδίαν, SPT. <i>2Macc. 6, 21,</i> prendre qqn à part, en particulier ;<br><b>      3</b> écarter, détourner ; <i>au pass</i>. être détourné (de sa route) : ὑπ' ἀνέμων, HDT. <i>2, 115,</i> par les vents ;<br><b>      4</b> séparer, intercepter : τὴν ἀναπνοήν τινος, PLUT. <i>Rom. 27,</i> étouffer <i>ou</i> étrangler qqn ; ἀπ. τινά, PLAT. <i>Phæd. 58</i> c, arrêter qqn dans sa marche ; ἀπολαμϐάνεσθαι ὑπ' ἀπλοίας, THC. <i>6, 22,</i> être arrêté en route par l’impossibilité de naviguer ; ἀπολαμφθέντες πάντοθεν, HDT. <i>5, 101,</i> cernés de tous côtés ; ἀπολαμϐάνειν τείχει, THC. <i>4, 102,</i> isoler par une muraille ; νόσῳ καὶ χειμῶνι ἀποληφθείς, DÉM. <i>98, 25,</i> bloqué par la maladie et le mauvais temps ; ἀπολαμϐάνειν ἐν τοῖς ἰδίοις λόγοις, PLAT. <i>Euthyd. 305</i> d, enfermer un interlocuteur dans ses propres paroles ;<br><b>      5</b> cesser de prendre <i>ou</i> de tenir, <i>d’où</i> laisser en repos, lâcher, HÉRON <i>Aut. 266, en parlant d’un cordon que l’opérateur vient de disposer</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Moy</i>. prendre à part, en particulier : τινα, NT. <i>Marc. 7, 33,</i> qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. ion</i>. ἀπολάμψομαι, HDT. <i>3, 146 ; 9, 38. Pass. ao</i>. ἀπελάμφθην (<i>d’où part</i>. ἀπολαμφθείς) HDT. <i>ll. cc. ; pf. ion</i>. ἀπολέλαμμαι, HPC. <i>Prorrh. 74, 77</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-λαμβανω - ἀπολαμβάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 11 versets de 7 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (6)</li>\n<li>Romains (1)</li>\n<li>Galates (1)</li>\n<li>Colossiens (1)</li>\n<li>2 Jean (1)</li>\n<li>3 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G619":"<h1>apolausis</h1>\n<p>Strong n° 619 <i>Prononciation [ap-ol'-ow-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>avoir la jouissance, profit</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπόλαυσις, εως (ἡ) :<br>      1</b> action de jouir de, THC. <i>2, 38 ; d’où</i> jouissance qu’on retire de qqe ch. ; <i>particul</i>. jouissance matérielle, plaisir des sens, XÉN. <i>Mem. 2, 1, 33, etc. ;</i> PLAT. <i>Tim. 83</i> a, <i>etc. ;</i> ARSTT. <i>H.A. 8, 8, etc. ;</i><br><b>      2</b> profit, HPC. <i>12, 26</i>.<br><span><b>Étym</b>. ἀπολαύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-λαυσις - ἀπόλαυσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G620":"<h1>apoleipo</h1>\n<p>Strong n° 620 <i>Prononciation [ap-ol-ipe'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>laisser, quitter, laisser derrière, laisser en réserve, abandonner</li>\n<li>déserter ou abandonner</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·λείπω</b> <span>(<i>f</i>. -λείψω, <i>ao.2</i> ἀπέλιπον, <i>pf</i>. ἀπολέλοιπα)</span><br><b>A <i>tr</i>.<br>   I</b> laisser en place, laisser : οὐδ' ἀπέλειπεν, OD. <i>9, 292,</i> il ne laissa rien, <i>càd</i>. il dévora tout ;<br><b>   II</b> laisser en partant, <i>càd. :</i><br><b>      1</b> laisser derrière soi, laisser à la postérité (des écrits, <i>etc</i>.) DL. <i>8, 58 ;</i><br><b>      2</b> laisser, quitter, abandonner : δόμον, IL. <i>12, 169,</i> une demeure ; <i>en parl. d’une femme qui abandonne son mari,</i> AND. <i>30, 43 ;</i> DÉM. <i>865, 6 (cf. en parl. du mari,</i> ἀποπέμπω) ; <i>en parl. de déserteurs,</i> DÉM. <i>1211, 2 ;</i><br><b>      3</b> laisser de côté, négliger : συχνά γε ἀπολείπω, PLAT. <i>Rsp. 509</i> c, j’omets bien des choses ;<br><b>      4</b> laisser derrière soi, dépasser (<i>en ce sens, surt. au moy</i>.) : τινά, XÉN. <i>Cyr. 8, 3, 25 ;</i> LYS. <i>190, 37,</i> qqn ; <i>fig</i>. τοσοῦτον ἀπ. τοὺς ἄλλους ἀνθρώπους περὶ τὸ φρονεῖν ὥστε, ISOCR. <i>50</i> e, surpasser tellement les autres hommes en sagesse que, <i>etc. ; p. suite,</i> laisser une distance, un intervalle, HDT. <i>6, 77 ;</i> ἀπ. ὡς πλέθρον, XÉN. <i>An. 6, 5, 11,</i> laisser une distance d’un plèthre environ ; <i>en parl. de mesures :</i> μέγαθος ἀπὸ τεσσέρων πήχεων ἀπολείπειν τρεῖς δακτύλους, HDT. <i>1, 60,</i> avoir une taille de quatre coudées moins trois doigts ; <i>en parl. de nombres, avec l’inf. :</i> βραχὺ ἀπέλιπον διακόσιαι γενέσθαι, THC. <i>7, 70,</i> il s’en fallut de peu qu’elles ne fussent deux cents ; <i>fig</i>. μικρὸν, ὀλίγον ἀπολείπω, <i>avec l’inf</i>. ATT. peu s’en faut que je ne, <i>etc. ;</i> οὐδὲν ἀπολείπετε <i>avec l’inf</i>. DÉM. <i>51, 25,</i> il ne s’en faut de rien que vous ne, <i>etc. ;</i><br><b>B <i>intr</i>.<br>   I</b> laisser derrière soi, abandonner, <i>d’où</i> s’éloigner : ἐκ τῶν Συρακουσῶν, THC. <i>5, 4,</i> de Syracuse ; <i>fig</i>. ὅθεν ἀπέλιπον, PLAT. <i>Gorg. 497</i> c, au point où je me suis arrêté (où j’ai laissé le discours, <i>etc</i>.) ; ἀπ. μικρόν, HÉRON <i>Aut. 271,</i> s’éloigner de peu ;<br><b>   II</b> faire défaut, manquer, <i>en parl. de fruits, de récoltes,</i> OD. <i>7, 117 ;</i> ὁ ποταμὸς ἀπολείπει, HDT. <i>2, 14, 93,</i> le fleuve baisse ; <i>en parl. de pers</i>. s’abandonner, perdre courage, XÉN. <i>Cyr. 4, 2, 3 ;</i> PLAT. <i>Ax. 365</i> a ;<br><b>C</b> <i>Pass. <span>(f</span></i>. ἀπολειφθήσομαι, <i>etc.)</i> être laissé en arrière, rester en arrière : ἀπολείπεσθαί τινος, DÉM. <i>51, 24,</i> être distancé par qqn, être inférieur à qqn ; ἔν τινι, ISOCR. <i>245</i> b, en qqe ch. ; ἀπ. καιροῦ, DÉM. <i>918, 19,</i> laisser échapper l’occasion (<i>litt</i>. rester en arrière) ; πλεῖστον ἀπολείπεσθαι τοῦ, <i>inf</i>. PLAT. <i>Ep. 321</i> e, être très loin de, <i>d’où</i> il s’en faut de beaucoup que, <i>etc. ; en parl. de choses,</i> être en reste, rester à faire, POL. <i>3, 39 ;</i> ἀπολείπεται λέγειν, DL. <i>7, 85,</i> il reste à dire ; <i>p. suite :</i><br><b>      1</b> être éloigné de : τῆς ἀληθηΐης, HDT. <i>2, 106,</i> de la vérité ; τῶν πραγμάτων, DÉM. <i>813 fin,</i> être éloigné des affaires, être tenu dans l’ignorance des affaires ;<br><b>      2</b> être privé de, manquer de : τάφου, SOPH. <i>El. 1169,</i> d’un tombeau ; παιδείας, DÉM. <i>270, 2,</i> manquer d’instruction ; τῶν πρὶν ἀπολειφθεὶς φρενῶν, EUR. <i>Or. 216,</i> étant privé de l’ancienne lucidité de mon esprit, <i>càd</i>. par suite de la démence ;<br><b>D</b> <b><i>Moy.</i></b> :<br><b>      1</b> laisser après soi, laisser à la postérité, HDT. <i>2, 134 ;</i><br><b>      2</b> laisser, abandonner, PLAT. <i>Phædr. 240</i> c.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-λειπω - ἀπολείπω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT).\n<ul>\n<li>2 Timothée (2)</li>\n<li>Hébreux (3)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G621":"<h1>apoleicho</h1>\n<p>Strong n° 621 <i>Prononciation [ap-ol-i'-kho]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lécher, essuyer en léchant</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·λείχω</b>, essuyer en léchant, ATH. <i>250</i> a ; NT. <i>Luc. 16, 21</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-λειχω - ἀπολείχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G622":"<h1>apollumi</h1>\n<p>Strong n° 622 <i>Prononciation [ap-ol'-loo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>détruire\n<ol type=\"a\">\n<li>démolir entièrement, abolir, mettre en ruine</li>\n<li>rendre inutile</li>\n<li>tuer</li>\n<li>déclarer que quelqu'un doit être mis à mort</li>\n<li>métaph. vouer à la misère éternelle en enfer</li>\n<li>périr, être perdu, ruiné, détruit</li>\n</ol>\n</li>\n<li>disparaître\n<ol type=\"a\">\n<li>perdre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπ·όλλυμι :<br>   I</b> <i>tr. au prés. et aux temps suiv. (impf</i>. ἀπώλλυν, <i>f</i>. ἀπολέσω, <i>att</i>. ἀπολῶ ; <i>ao</i>. ἀπώλεσα ; <i>pf.1</i> ἀπολώλεκα ; <i>v. ci-dessous pf.2</i>) :<br><b>      1</b> perdre, faire périr : λαὸν Ἀχαιῶν, IL. <i>5, 758, etc</i>. l’armée des Grecs ; <i>en parl. de choses :</i> Ἴλιον, IL. <i>5, 648,</i> détruire Ilion ; ἀ. τί τινος, DÉM. <i>107, 8,</i> sacrifier une chose en considération d’une autre ; <i>fig</i>. ἀπολεῖς με, AR. <i>Ach. 470,</i> tu me feras mourir (avec tes questions, <i>etc</i>.) ;<br><b>      2</b> perdre, subir une perte : ἀπ. τινα, IL. <i>18, 82 ;</i> OD. <i>2, 46, etc</i>. perdre qqn (un parent, un ami, <i>etc</i>.) ; ἀ. τὴν ἀρχὴν ὑπό τινος, XÉN. <i>An. 3, 4, 11,</i> être dépossédé de l’empire par qqn ;<br><b>   II</b> <i>intr. (au pf.2</i> ἀπόλωλα, <i>au pl.q.pf</i>. ἀπολώλειν, <i>et au moy</i>. <b>ἀπόλλυμαι</b> <span>(<i>f</i>. ἀπολοῦμαι, <i>ao.2</i> ἀπωλόμην)</span>) :<br><b>      1</b> être arraché pour sa perte de : ἀπωλόμην, EUR. <i>I.T. 541,</i> j’ai été arraché à ma patrie, <i>d’où</i> périr, être perdu : ἀπόλωλας, AR. <i>Nub. 1077 ;</i> PLUT. <i>M. 185</i> e, <i>etc</i>. tu es perdu ; ἀπώλετο λυγρῷ ὀλέθρῳ, OD. <i>3, 87, ou</i> ἀπόλωλε κακὸν μόρον, OD. <i>1, 166 ou</i> ὄλεθρον, OD. <i>9, 303,</i> il mourut, il est mort d’une mort lamentable ; <i>surt. dans les imprécations :</i> κάκιστ' ἀπολοίμην εἰ, AR. <i>Ach. 151, etc</i>. que je périsse misérablement si… ! ὁ κάκιστ' ἀπολούμενος, AR. <i>Pl. 713, etc. ;</i> LUC. <i>D. deor. 14, 2,</i> misérable, <i>litt</i>. destiné à la plus misérable fin ; <i>avec un rég</i>. ἀπ. ὑπό τινος, HDT. <i>5, 126,</i> périr de la main <i>ou</i> par l’intervention de qqn ;<br><b>      2</b> <i>au sens mor</i>. se perdre, se laisser corrompre, EUR. <i>El. 1065 ;</i><br><b>      3</b> se perdre, s’évanouir, s’échapper, OD. <i>11, 586</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. ind. 3 pl</i>. ἀπολλύασι, THC. <i>7, 51. Ao. épq</i>. ἀπόλεσσα, IL. <i>1, 268. Pf. 2 au sens trans</i>. DH. <i>9, 40. Pl.q.pf</i>. ἀπολώλειν <i>ou</i> ἀπωλώλειν, ATT. — <i>Pass. fut. réc. part</i>. ἀπολεσθησόμενος, GAL. <i>9, 728. Ao</i>. ἀπωλέσθην, SPT. <i>Ps. 82, 18. — Moy. fut. ion</i>. ἀπολέομαι, HDT. <i>8, 57, etc. ; d’où part</i>. ἀπολεύμενοι, HDT. <i>7, 209 dout. Ao.2, 3 pl. épq</i>. ἀπόλοντο, IL. <i>2, 162 ;</i> OD. <i>3, 185, etc. ; opt. 3 pl. ion</i>. ἀπολοίατο, OD. <i>9, 554. Ao. itér. 3 sg</i>. ἀπολέσκετο, OD. <i>11, 586</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-ολλυμι - ἀπόλλυμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n91 fois dans 85 versets de 15 livres bibliques (NT)\n<ul>\n<li>Matthieu (20)</li>\n<li>Marc (10)</li>\n<li>Luc (28)</li>\n<li>Jean (11)</li>\n<li>Actes (1)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (6)</li>\n<li>2 Corinthiens (3)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (2)</li>\n<li>2 Jean (1)</li>\n<li>Jude (2)</li>\n</ul>\n</td></tr>\n</table>","G623":"<h1>Apolluon</h1>\n<p>Strong n° 623 <i>Prononciation [ap-ol-loo'-ohn]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Apollyon = « Destructeur » (<a class=\"ref\" data-r=\"REV9.11\">Apocalypse 9.11</a>)\n<ol><li>l'ange des abîmes, le Destructeur, « Qui fait périr »</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Απολλυων - Ἀπολλύων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G624":"<h1>Apollonia</h1>\n<p>Strong n° 624 <i>Prononciation [ap-ol-lo-nee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Apollonie (Angl. Apollonia) = « appartenant à Apollon »\n<ol><li>cité maritime de Macédoine, à un jour de voyage de Amphipolis</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἀπολλωνία, ας (ἡ)</b> Apollonie, <i>n. de v. :</i><br><b>      1</b> <i>de Thrace (auj</i>. Sozopol (Bulgarie)) HDT. <i>4, 90, etc. ;</i><br><b>      2</b> <i>de Macédoine,</i> XÉN. <i>Hell. 5, 2, 11, etc. ;</i><br><b>      3</b> <i>d’Épire,</i> HDT. <i>9, 92 ;</i> THC. <i>1, 26, etc. ;</i><br><b>      4</b> <i>de Mysie,</i> XÉN. <i>An. 7, 8, 15 ;</i><br><b>      5</b> <i>de Bithynie,</i> PLUT. <i>Luc. 11, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -ίη, HDT. <i>4, 90</i>.<br><span><b>Étym</b>. Ἀπόλλων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Απολλωνια - Ἀπολλωνία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G625":"<h1>Apollos</h1>\n<p>Strong n° 625 <i>Prononciation [ap-ol-loce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Apollos = « donné par Apollon »\n<ol><li>un Juif d'Alexandrie, très écouté, versé dans les Ecritures, et qui devint Chrétien et enseignant du Christianisme</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Απολλως - Ἀπολλῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>1 Corinthiens (7)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G626":"<h1>apologeomai</h1>\n<p>Strong n° 626 <i>Prononciation [ap-ol-og-eh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se défendre, prendre sa propre défense, plaider pour soi</li>\n<li>défendre une personne ou une chose</li>\n<li>donner un récit complet\n<ol type=\"a\">\n<li>calculer ou bien considérer</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπολογέομαι-οῦμαι</b> <span>(<i>f</i>. ήσομαι, <i>ao</i>. ἀπελογησάμην, <i>pf</i>. ἀπολελόγημαι)</span><br><b>      1</b> plaider pour soi, se défendre, <i>abs</i>. HDT. <i>6, 136 ;</i> ATT. ; ὁ ἀπολογούμενος, AR. <i>Vesp. 778 ;</i> AND. <i>1, 29,</i> le défendeur ; ἀπ. ὑπὲρ ἑαυτοῦ, PLAT. <i>Ap. 30</i> d, plaider pour soi-même ; ἀπ. πρός τινα, répondre aux accusations de qqn, PLAT. <i>Ap. 24</i> b ; <i>ou</i> se défendre devant qqn, EUP. <i>357 Kock ;</i> ἀπ. πρός τι, ANT. <i>119, 30 ;</i> THC. <i>6, 29, ou</i> περί τινος, THC. <i>1, 72, etc. ;</i> XÉN. <i>Cyr. 2, 2, 13 ; An. 5, 6, 3, etc</i>. se défendre contre une accusation <i>ou</i> au sujet d’une accusation ; <i>postér. avec le dat</i>. κατηγορίαις, PLUT. <i>Them. 23,</i> se défendre contre des accusations ; <i>avec l’acc. de la chose alléguée pour la défense :</i> ἀπ. τι, THC. <i>3, 62 ;</i> XÉN. <i>Mem. 4, 8, 4 ;</i> PLAT. <i>Gorg. 521</i> e, <i>etc</i>. alléguer qqe ch. ; <i>avec une conj</i>. ἀπ. ὡς, PLAT. <i>Phæd. 69</i> d ; ὅτι, XÉN. <i>Œc. 11, 22,</i> alléguer que ; <i>avec l’acc. du grief :</i> ἀπ. τὰς διαϐολάς, THC. <i>8, 109,</i> réfuter les accusations (<i>sel. Cobet</i> ἀπολύσεται) ;<br><b>      2</b> plaider pour un autre : ὑπέρ τινος, EUR. <i>Bacch. 41,</i> pour qqn ; τινὶ ὑπέρ τινος, HDT. <i>7, 161,</i> contre qqn pour une autre personne.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. pass</i>. ἀπελογήθην <i>au sens act</i>. ANT. <i>2, γ, 1 ; 2, δ, 3, etc. ;</i> COM. (<i>Com. fr. 3, 388</i>) ; <i>au sens pass</i>. XÉN. <i>Hell. 1, 4, 13</i>.<br><span><b>Étym</b>. ἀπόλογος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-λογεομαι - ἀπολογέομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (6)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G627":"<h1>apologia</h1>\n<p>Strong n° 627 Prononciation [ap-ol-og-ee'-ah]</p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>défense verbale, plaidoirie, plaidoyer</li>\n<li>un argument raisonné</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπολογία, ας (ἡ) :<br>      1</b> défense, justification, THC. <i>3, 61 ;</i> XÉN. <i>Mem. 4, 8, 5, etc. ;</i> PLAT. <i>Ap. 28</i> a, <i>etc. ;</i> ἀπολογίαν ποιεῖσθαι, LYS. <i>142, 23 ;</i> IS. <i>62, 29, etc</i>. présenter sa défense, se défendre ;<br><b>      2</b> réponse, NT. <i>1Petr. 3, 15</i>.<br><span><b>Étym</b>. ἀπόλογος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απολογια - ἀπολογία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 6 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Philippiens (2)</li>\n<li>2 Timothée (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G628":"<h1>apolouo</h1>\n<p>Strong n° 628 <i>Prononciation [ap-ol-oo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>laver ou être lavé, se purifier, se laver</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·λούω</b> <span>(<i>f</i>. -ούσω, <i>ao</i>. ἀπέλουσα)</span> ôter en lavant : τι, IL. <i>14, 7,</i> qqe ch. (sueur, sang, <i>etc</i>.) ; τινά, AR. <i>Vesp. 118 ;</i> PLAT. <i>Crat. 405</i> b, laver <i>ou</i> baigner qqn ;<br><b><i>Moy.</i></b> :<br><b>      1</b> ôter en se lavant : τι, OD. <i>6, 219,</i> qqe ch. (sueur, poussière, <i>etc</i>.) ;<br><b>      2</b> <i>p. ext</i>. laver sur soi, nettoyer en se lavant : τὸ σῶμα, LGS <i>1, 13,</i> se laver le corps, se baigner ; <i>abs</i>. se laver, IL. <i>23, 41 ;</i> se baigner, LUC. <i>Lex. 2</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. 3 sg</i>. ἀπέλου, AR. <i>l. c. Moy. part. prés. contr</i>. ἀπολούμενος, LUC. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-λουω - ἀπολούω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G629":"<h1>apolutrosis</h1>\n<p>Strong n° 629 <i>Prononciation [ap-ol-oo'-tro-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>libération effectuée suite au paiement d'une rançon\n<ol type=\"a\">\n<li>rédemption, délivrance</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπολύτρωσις, εως (ἡ) :<br>      1</b> rachat d’un captif, PLUT. <i>Pomp. 24 ;</i> JOS. <i>A.J. 12, 2, 3 ;</i><br><b>      2</b> <i>t. eccl</i>. rédemption, NT. <i>Rom. 3, 24 ; Eph. 1, 7</i>.<br><span><b>Étym</b>. ἀπολυτρόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-λυτρωσις - ἀπολύτρωσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 6 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (3)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G630":"<h1>apoluo</h1>\n<p>Strong n° 630 <i>Prononciation [ap-ol-oo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>libérer, délier, détacher</li>\n<li>laisser aller, congédier, (ne pas détenir plus longtemps)\n<ol type=\"a\">\n<li>requérant à qui on donne l'autorisation de partir</li>\n<li>ordonner le départ, renvoyer</li>\n</ol>\n</li>\n<li>libérer, relâcher\n<ol type=\"a\">\n<li>un captif, qui perd ses liens et s'en va librement</li>\n<li>acquitter un accusé d'un crime et le remettre en liberté</li>\n<li>libérer avec indulgence un prisonnier</li>\n<li>libérer un débiteur, ne rien lui réclamer, lui remettre sa dette</li>\n</ol>\n</li>\n<li>divorcer, renvoyer de la maison, répudier. L'épouse d'un Grec ou d'un Romain pouvait divorcer de son mari</li>\n<li>s'en aller, prendre congé, partir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·λύω</b> <span>(<i>f</i>. ύσω, <i>ao</i>. ἀπέλυσα, <i>pf</i>. ἀπολέλυκα)</span><br><b>   I</b> <i>au propre :</i><br><b>      1</b> délier, détacher : ἱμάντα, OD. <i>21, 46,</i> une courroie ;<br><b>      2</b> mettre au jour ; <i>au pass</i>. être mis au jour, <i>en parl. d’un enfant,</i> HPC. <i>144</i> e ; <i>261, 49 ; en parl. de la femme,</i> être délivrée, HPC. <i>261, 52 ; 262, 39 ; etc. ; en parl. de la matrice,</i> être délivré de, HPC. <i>260, 11 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> libérer un captif moyennant rançon, IL. <i>1, 95, etc. ;</i> ATT. ; ἀπολύεσθαι πολλῶν χρημάτων, XÉN. <i>Hell. 4, 8, 21,</i> être libéré moyennant une forte somme ;<br><b>      2</b> <i>t. de droit :</i> ἀπ. τινὰ αἰτίας, HDT. <i>9, 88 ;</i> XÉN. <i>An. 6, 6, 16, etc</i>. absoudre qqn d’une accusation ; <i>avec</i> μή <i>et l’inf. :</i> ἀπ. τινὰ μὴ φῶρα εἶναι, HDT. <i>2, 174,</i> acquitter qqn comme n’étant pas un voleur ; <i>abs</i>. AR. <i>Vesp. 988, etc. ; au pass</i>. être acquitté, être absous, THC. <i>6, 29, etc. ;</i><br><b>      3</b> acquitter (une dette), payer : ἀπ. ἀνάλωμα, PLAT. <i>Crat. 417</i> b, couvrir une dépense ;<br><b>      4</b> congédier, renvoyer, <i>particul</i>. licencier (une armée) XÉN. <i>Hell. 6, 5, 21 ;</i> répudier (une femme) NT. <i>Matth. 1, 19 ;</i> se séparer (d’un mari) DS. <i>12, 18 ; en gén</i>. τινὰ ἀπ. ἄδειπνον, AR. <i>Ach. 1155,</i> renvoyer qqn sans souper ;<br><b>      5</b> affranchir, libérer : τινά τινος, HDT. <i>2, 30 ;</i> XÉN. <i>Cyr. 8, 3, 47 ;</i> PLAT. <i>Rsp. 865</i> a, qqn d’une charge, d’un souci, <i>etc. ;</i> τὴν ψυχὴν ἀπὸ τοῦ σώματος κοινωνίας, PLAT. <i>Phæd. 64</i> e, affranchir l’âme de la communauté avec le corps ; <i>au pass</i>. τῆς στρατηΐης ἀπολελύσθαι, HDT. <i>4, 84,</i> être affranchi du service militaire ; τῆς ἀρχῆς ἀπ. THC. <i>2, 8,</i> être affranchi de l’autorité (de qqn) ;<br><b>      6</b> <i>t. de log. et de gr., au pf. pass</i>. ἀπολελύσθαι, être indépendant, être absolu ; ἀπολελυμένος, absolu, ARSTT. SEXT. DYSC. <i>etc. ou</i> non rythmé, HÉPH. <i>Poem. 5 ;</i> HDN GR. ;<br><b><i>Moy.</i></b> :<br><b>   I <i>tr</i>.<br>      1</b> écarter de soi : διαϐολάς, THC. <i>8, 87 ;</i> PLAT. <i>Ap. 37</i> b ; αἰτίαν, THC. <i>5, 75 ;</i> DÉM. <i>191, 11, etc</i>. des attaques, une accusation ; <i>abs</i>. ὁ δὲ ἀπολυόμενος ἔφη, HDT. <i>8, 59,</i> il dit pour sa défense ; <i>avec le gén. :</i> τινὰ ἀπ. τινός, PLAT. <i>Leg. 637</i> c, décharger <i>ou</i> disculper qqn de qqe accusation ;<br><b>      2</b> délivrer : τοὺς Ἕλληνας ἀπ. δουλείας, PLAT. <i>Menex. 245</i> a, les Grecs de la servitude ;<br><b>   II <i>intr</i>.<br>      1</b> se détacher, se séparer : ἀλλήλων, ARSTT. <i>Metaph. 6, 6, 5, ou</i> ἀπ' ἀλλήλων, ARSTT. <i>Phys. 1, 2, 6,</i> les uns des autres ; <i>abs</i>. ἀπολελυμένος, détaché, séparé, <i>en parl. d’organes,</i> ARSTT. <i>H.A. 2, 1, 41 ; 4, 8, 7, etc. ;</i><br><b>      2</b> s’éloigner, partir, POL. <i>2, 34, 12, etc. ; d’où</i> quitter la vie, mourir, SOPH. <i>Ant. 1314</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2 moy. part. épq. plur. neutre</i> ἀπολύμενα, <i>au sens pass</i>. OPP. <i>C. 8, 128</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-λυω - ἀπολύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n69 fois dans 62 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (19)</li>\n<li>Marc (12)</li>\n<li>Luc (16)</li>\n<li>Jean (5)</li>\n<li>Actes (16)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G631":"<h1>apomassomai</h1>\n<p>Strong n° 631 <i>Prononciation [ap-om-as'-som-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>essuyer, effacer</li>\n<li>se secouer la poussière pour la faire partir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·μάσσω</b>, <i>att</i>. <b>-μάττω</b>, enlever en pétrissant, en frottant, <i>d’où :</i><br><b>      1</b> essuyer : δάκρυα χλαμύδι, POL. <i>15, 26, 3,</i> essuyer des larmes avec sa chlamyde ; <i>joint à</i> καθαίρω, LUC. <i>Nec. 7 ; fig</i>. τοὺς τελουμένους τῷ πηλῷ καὶ τοῖς πιτύροις, DÉM. <i>313, 17,</i> purifier les initiés en les frottant de boue et de son ;<br><b>      2</b> racler, raser, <i>en parl. des marchands qui passent la main sur une mesure pleine pour la niveler :</i> χοῖνιξ ἀπομεμαγμένη, LUC. <i>Nav. 25,</i> chénice bien nivelée ; <i>prov</i>. <span>κενεὰν ἀπομάξαι</span> (<i>s.-e</i>. χοίνικα) THCR. <i>Idyl. 15, 95,</i> niveler une mesure vide, <i>càd</i>. faire une besogne vaine ;<br><b>      3</b> prendre une empreinte : ἐν μαλακοῖς σχήματα, PLAT. <i>Tim. 50</i> e, modeler des figures dans une pâte molle (cire, plâtre, <i>etc</i>.) ;<br><b><i>Moy.</i></b> :<br><b>   I</b> essuyer sur soi <i>ou</i> pour soi, <i>d’où :</i><br><b>      1</b> ôter en s’essuyant : τι, CALL. <i>Del. 14,</i> qqe ch. (de l’écume, <i>etc</i>.) ;<br><b>      2</b> essuyer pour soi : τὰς χεῖρας χειρομάκτρῳ, ATH. <i>410</i> b, s’essuyer les mains avec une serviette ; <i>abs</i>. s’essuyer la bouche, POÈT. (ATH. <i>2</i> a) ; Ἀχιλλείων ἀπ. AR. <i>Eq. 819,</i> s’essuyer (les mains) à du pain de choix, <i>càd</i>. manger du pain de choix ;<br><b>   II</b> prendre sur soi-même l’empreinte de, se modeler sur, AR. <i>Ran. 1040 ;</i> παρ' ἀλλήλων ἀπ. ARSTT. <i>Nic. 9, 12, 3,</i> se modeler les uns sur les autres.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-μασσομαι - ἀπομάσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</ul>\n</td></tr>\n</table>","G632":"<h1>aponemo</h1>\n<p>Strong n° 632 <i>Prononciation [ap-on-em'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>assigner, céder, doter, honorer, partager, accorder</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·νέμω</b> <span>(<i>f</i>. -νεμῶ, <i>ao</i>. ἀπένειμα, <i>pf</i>. ἀπονενέμηκα)</span><br><b>      1</b> attribuer en partage, attribuer, assigner : τί τινι, HDT. <i>2, 54 ;</i> PLAT. <i>Leg. 757</i> c, <i>etc. ;</i> ISOCR. <i>11</i> d, <i>etc</i>. qqe ch. à qqn ; <i>d’où</i> accorder, concéder, <i>acc</i>. LUC. <i>Nigr. 14 ;</i> rapporter, déclarer, <i>acc</i>. PD. <i>I. 2, 47 ;</i><br><b>      2</b> diviser, séparer, PLAT. <i>Pol. 307</i> b, <i>etc. ; p. suite,</i> mettre à part, excepter, PLAT. <i>Leg. 771</i> c, <i>etc. ;</i><br><b><i>Moy.</i></b> s’attribuer en partage, s’attribuer : τι, PLAT. <i>Leg. 739</i> b, <i>etc</i>. qqe ch. ; <i>ou</i> τινος, PLAT. <i>Rsp. 574</i> a, une part de qqe ch. ; <i>d’où</i> faire son profit de, <i>acc</i>. AR. <i>Av. 1289</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-νεμω - ἀπονέμω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</ul>\n</td></tr>\n</table>","G633":"<h1>aponipto</h1>\n<p>Strong n° 633 <i>Prononciation [ap-on-ip'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>laver, se laver, nettoyer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·νίπτω</b>, <i>c</i>. ἀπονίζω, PLUT. <i>Phoc. 18</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-νιπτω - ἀπονίπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G634":"<h1>apopipto</h1>\n<p>Strong n° 634 <i>Prononciation [ap-op-ip'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tomber, chuter, glisser, faire une faute</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·πίπτω</b> <span>(<i>f</i>. ἀποπεσοῦμαι, <i>etc</i>.)</span><br><b>      1</b> tomber de : ἀπό τινος, HDT. <i>3, 130, ou simpl</i>. τινός, HDT. <i>3, 64,</i> de qqe ch. ; ἐκ πέτρης, OD. <i>24, 7,</i> d’un rocher ; <i>abs</i>. IL. <i>14, 351 ;</i> THC. <i>4, 4, etc. ; fig</i>. τῆς ἐλπίδος, POL. <i>9, 7, 1,</i> être précipité de ses espérances ; <i>abs</i>. manquer le but, être déçu, POL. <i>4, 36, 5 ;</i><br><b>      2</b> sauter de : τῶν ἵππων, POL. <i>11, 21, 3,</i> de leurs chevaux ; ἐπὶ τὴν γῆν, POL. <i>35, 5, 2,</i> sauter et tomber (droit sur ses jambes) à terre.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. sbj. 3 sg. épq</i>. ἀποπέσῃσιν <span>[ᾱ]</span> OD. <i>24, 7</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-πιπτω - ἀποπίπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G635":"<h1>apoplanao</h1>\n<p>Strong n° 635 <i>Prononciation [ap-op-lan-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>causer l'égarement</li>\n<li>amener loin de la vérité vers l'erreur</li>\n<li>s'égarer, être dans l'erreur, faire errer, séduire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·πλανάω-ῶ</b> <span>[ᾰν]</span> égarer, écarter de, POL. <i>3, 57, 4 ;</i> LUC. <i>Gymn. 21 ; fig</i>. τινα ἀπὸ τῆς ὑποθέσεως, ESCHN. <i>79, 6,</i> écarter qqn du sujet ;<br><b><i>Moy.</i></b> s’écarter de, <i>gén</i>. ISOCR. <i>155</i> d ; LUC. <i>Nec. 19 ; abs</i>. faire fausse route, s’égarer, ARSTT. <i>H.A. 5, 23, 1</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-πλαναω - ἀποπλανάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbes</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G636":"<h1>apopleo</h1>\n<p>Strong n° 636 <i>Prononciation [ap-op-leh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>naviguer, partir par bateau, s'embarquer, prendre la mer, lever l'ancre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·πλέω</b> <span>(<i>f</i>. -πλεύσομαι <i>ou</i> -πλευσοῦμαι)</span><br><b>      1</b> s’éloigner par mer, THC. <i>1, 55 ; 6, 61 ;</i><br><b>      2</b> revenir par mer, XÉN. <i>Hell. 1, 1, 13, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut</i>. ἀποπλευσοῦμαι, PLAT. <i>Hipp. mi. 371</i> b. <i>Prés. épq. et ion</i>. ἀποπλείω, IL. <i>9, 418 ; cf</i>. ἀποπλώω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-πλεω - ἀποπλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (4)</li>\n</ul>\n</td></tr>\n</table>","G637":"<h1>apopluno</h1>\n<p>Strong n° 637 <i>Prononciation [ap-op-loo'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>laver, nettoyer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·πλύνω</b>, laver, OD. <i>6, 95 ;</i> PLAT. <i>Tim. 65</i> d ; LUC. <i>Anach. 29, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-πλυνω - ἀποπλύνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G638":"<h1>apopnigo</h1>\n<p>Strong n° 638 <i>Prononciation [ap-op-nee'-go]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>étouffer\n<ol type=\"a\">\n<li>suffoquer dans l'eau, se noyer</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·πνίγω</b> <span>(<i>f</i>. -πνίξω <i>ou</i> -πνίξομαι, <i>ao</i>. ἀπέπνιξα, <i>pf. inus. ; pass. fut.2</i> -πνιγήσομαι, <i>ao.2</i> ἀπεπνίγην, <i>pf</i>. ἀποπέπνιγμαι)</span> étouffer, suffoquer (qqn) HDT. <i>2, 169, etc. ;</i> ATT. (AR. <i>Vesp. 1034, etc. ;</i> XÉN. <i>Hell. 3, 1, 14, etc.) ; au pass</i>. être étouffé, XÉN. <i>Cyr. 8, 2, 11, etc. ; particul</i>. être asphyxié par l’eau, DÉM. <i>883 fin ; fig</i>. suffoquer (de colère, <i>etc</i>.) : ἐπί τινι, DÉM. <i>403, 17,</i> à cause de qqe ch. ; <i>abs</i>. LUC. <i>Gall. 28</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut</i>. ἀποπνίξω, COM. <i>fr. 2, 686 ;</i> ANTIPH. <i>3, 93 ;</i> LUC. <i>Char. 23. Fut. pass</i>. ἀποπνιγήσομαι <span>[ῐ]</span> AR. <i>Nub. 1504 ;</i> LUC. <i>D. mar. 6, 3. Ao.2</i> ἀπεπνίγην <span>[ῐ]</span> PLAT. <i>Gorg. 512</i> a, <i>etc. Ao.1 réc</i>. ἀπεπνίχθην, ARÉT. <i>1, 7, p. 11 (Adams</i>) ; BABR. <i>49. Fut. ant. inf</i>. ἀποπεπνίξεσθαι, EUN. <i>V. soph. p. 38</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-πνιγω - ἀποπνίγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (2)</li>\n</ul>\n</ul>\n</td></tr>\n</table>","G639":"<h1>aporeo</h1>\n<p>Strong n° 639 <i>Prononciation [ap-or-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être sans ressources, dans l'embarras, dans le besoin, dans le doute, ne pas savoir de quel côté se tourner</li>\n<li>être perdu, affolé</li>\n<li>ne pas savoir quoi décider, être perplexe, être incertain, ne pas savoir quoi faire</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n① <b>ἀπορέω-ῶ</b> <span>(<i>f</i>. ήσω, <i>ao</i>. ἠπόρησα, <i>pf</i>. ἠπόρηκα)</span><br><b>      1</b> être sans ressources, manquer de, <i>gén. :</i> τροφῆς, THC. <i>8, 81 ;</i> συμμάχων, XÉN. <i>Cyr. 4, 2, 39, etc.,</i> manquer de nourriture, d’alliés, <i>etc. ; cf</i>. PLAT. <i>Rsp. 557</i> d, <i>etc. ; abs</i>. être dans le besoin, être pauvre, <i>p. opp. à</i> πλουτέω, PLAT. <i>Conv. 203</i> e ;<br><b>      2</b> être dans l’embarras, ne savoir pas, <i>abs</i>. HDT. <i>1, 191, etc. ;</i> THC. <i>2, 102 ;</i> XÉN. <i>Hell. 4, 5, 17, etc. ;</i> ἀπ. τινι, XÉN. <i>An. 1, 3, 8 ;</i> ISOCR. <i>71</i> b, être dans l’embarras par suite de qqe ch. ; ἀπ. περί τινος, PLAT. <i>Gorg. 462</i> b, <i>etc. ;</i> διά τι, AND. <i>30, 15,</i> ἔς τι, SOPH. <i>Tr. 1243, ou simpl</i>. ἀπ. τι, HDT. <i>3, 4 ;</i> ATT. (THC. <i>5, 40 ;</i> XÉN. <i>Hell. 6, 1, 4, etc</i>.) être dans l’embarras, dans l’incertitude au sujet de qqe ch. ; <i>avec une prop. précédée d’un relat</i>. (ὅ τι, SOPH. <i>O.R. 486 ;</i> XÉN. <i>Cyr. 4, 5, 14, etc. ;</i> τίνα τρόπον, DÉM. <i>29, 10 ;</i> ὅτῳ τρόπῳ, THC. <i>3, 109, etc.) ou d’une conj</i>. (ὅπως, HDT. <i>1, 75, etc. ;</i> ὅπῃ, THC. <i>1, 107, etc. ;</i> PLAT. <i>Soph. 231</i> c ; πόθεν, HYPÉR. <i>Epit. 32 ;</i> ὁπόθεν, THC. <i>8, 80, etc. ;</i> ἀπορῶ ὅ τι λέξω, SOPH. <i>O.R. 486,</i> je ne sais que dire ; ἀπορῶν ποῖ τράποιτο, THC. <i>1, 63,</i> ne sachant de quel côté se tourner ; ἀπ. ὅπως δεῖ χρῆσθαι, XÉN. <i>Cyr. 4, 3, 19,</i> ne savoir comment faire ; ἀπ. εἰ, PLAT. <i>Prot. 326</i> e, être dans l’embarras pour savoir si ; ἀπ. μή, PLAT. <i>2 Alc. 142</i> d, douter que, craindre que… ne ; <i>avec un inf</i>. ἀπ. κρῖναι, AR. <i>Vesp. 590 (cf</i>. XÉN. <i>Œc. 8, 10 ;</i> PLAT. <i>Pol. 262</i> e ; LYS. <i>115, 2, etc</i>.) être dans l’embarras pour juger ; <i>au pass</i>. être un objet de doute, être mis en doute <i>ou</i> en question : οὐδὲν ἀπορεῖται τῶν δεομένων γίγνεσθαι, XÉN. <i>Lac. 13, 7,</i> il n’y a aucun doute sur ce qui doit arriver ; τὸ ἀπορούμενον, PLAT. <i>Soph. 243</i> b ; τὸ ἀπορηθέν, PLAT. <i>Leg. 799</i> c ; τὰ ἠπορημένα, ARSTT. <i>Pol. 3, 10, 5,</i> ce qui est un sujet de doute ;<br><b><i>Moy.</i></b> <span>(<i>ao. pass</i>. ἠπορήθην)</span> être dans l’embarras, être perplexe, EUR. <i>I.A. 537 ; avec</i> ὅ τι : ἠπορούμην ὅ τι χρησαίμην, LYS. <i>97, 17,</i> je ne savais que faire.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. ind. 1 pl. lac</i>. ἀπορίομες, XÉN. <i>Hell. 1, 1, 23. — Pass. prés. part. ion</i>. ἀπορεύμενος, HDT. <i>2, 121, au sens moy., ou</i> -εόμενος, HPC. <i>8, 35, etc. au sens pass. Ao</i>. ἠπορήθην <i>au sens moy</i>. DÉM. <i>27, 53 ; au sens pass</i>. PLAT. <i>Leg. 799</i> c ; ARSTT. <i>Pol. 8, 6, etc. Pf</i>. ἠπόρημαι <i>au sens moy</i>. EUR. <i>I.A. 537 ; au sens pass</i>. ARSTT. <i>H.A. 4, 9, 3 ;</i> LUC. <i>Philops. 1. — Moy. f</i>. ἀπορήσομαι <i>au sens pass</i>. ARSTT. <i>M. mor. 2, 3, 16</i>.<br><span><b>Étym</b>. ἄπορος.</span><br><br>\n② <b>ἀπορέω</b>, <i>v</i>. ἀφοράω ci-dessous.<br>\n<b>ἀφ·οράω-ῶ</b> <span>(<i>impf</i>. ἀφεώρων, <i>f</i>. ἀπόψομαι, <i>ao.2</i> ἀπεῖδον, <i>pf</i>. ἀφεώρακα)</span><br><b>      1</b> regarder de loin, HDT. <i>4, 22 ;</i> TIMOCL. (ATH. <i>407</i> e) ; TH. <i>H.P. 4, 4, 8, etc. ;</i><br><b>      2</b> fixer les yeux de différents points sur une même chose, <i>d’où</i> avoir en plein sous les yeux, <i>acc</i>. HDT. <i>8, 37 ; p. suite,</i> fixer les yeux sur, contempler, regarder : τι, DÉM. <i>1472, 15 ;</i> πρός τι, THC. <i>7, 71 ;</i> PLAT. <i>Phil. 17</i> c ; <i>Rsp. 585</i> a ; PLUT. <i>M. 116</i> d, <i>227</i> f ; εἴς τι, PLUT. <i>Lyc. 7,</i> qqe ch. ; πρός τινα, PLUT. <i>M. 119</i> c, <i>181</i> e ; <i>etc. ;</i> εἴς τινα, LUC. <i>Philops. 30 ;</i> ἐπί τινα, PLUT. <i>Cato mi. 50,</i> fixer les yeux sur qqn ;<br><b>      3</b> détourner les yeux, <i>p. suite,</i> se détourner, <i>d’où</i> avoir le dos tourné, XÉN. <i>Cyr. 7, 1, 36 ;</i><br><b><i>Moy.</i></b> regarder <i>ou</i> observer de loin, <i>acc</i>. AR. <i>Nub. 281</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἀπορέω, <i>d’où impf</i>. ἀπώρεον, HDT. <i>8, 37</i>.<br><span><b>Étym</b>. ἀπό, ὁράω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-πορεω - ἀπορέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G640":"<h1>aporia</h1>\n<p>Strong n° 640 <i>Prononciation [ap-or-ee'-a]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>l'état de celui qui est dans la perplexité, l'embarras, l'angoisse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπορία, ας (ἡ) :<br>   I</b> difficulté de passer, XÉN. <i>An. 5, 6, 10 ;</i><br><b>   II</b> manque de ressources, <i>d’où :</i><br><b>      1</b> manque, privation, <i>en gén</i>. ATT. : τροφῆς, THC. <i>1, 11,</i> manque de nourriture ; ἀπώλλυντο ἀπορίᾳ τοῦ θεραπεύοντος, THC. <i>2, 51,</i> ils périssaient faute de qqn pour les soigner ;<br><b>      2</b> <i>abs</i>. besoin, indigence, pauvreté, THC. <i>1, 123, etc. ; p. opp. à</i> εὐπορία, ARSTT. <i>Pol. 3, 8, 4 ; joint à</i> πενία, AND. <i>18, 42 ; au plur</i>. DÉM. <i>386, 15 ;</i><br><b>      3</b> embarras, difficulté : ἐς ἀπορίην (<i>ion</i>.) πολλὴν ἀπιγμένος, HDT. <i>1, 79,</i> réduit à un extrême embarras ; ἀπορίῃσιν ἐνέχεσθαι, HDT. <i>1, 190 ;</i> ἐν ἀπορίῃσι ἔχεσθαι, HDT. <i>4, 131 ; ou</i> ἐν ἀπορίᾳ (<i>ion</i>. ἐν ἀπορίῃ, HDT. <i>9, 98</i>) ἔχεσθαι, PLAT. <i>Gorg. 522</i> a ; ἀπορίᾳ ἔχεσθαι, PLAT. <i>Prot. 321</i> c ; ἐν ἀπορίαις εἶναι, PLAT. <i>Pol. 273</i> d, être dans l’embarras ; εἰς ἀπορίαν ἐμπίπτειν, PLAT. <i>Theæt. 174</i> c, tomber dans l’embarras ; ἀπορίας ὕπο, EUR. <i>Or. 232,</i> par suite de l’embarras où l’on est, parce qu’ils ne savent (les malades) quel parti prendre, parce qu’ils se trouvent mal, quoi qu’ils fassent ; ἀπ. τινός, difficulté d’atteindre <i>ou</i> de punir (un meurtrier) ANT. <i>119, 27 ;</i> ἀπ. τοῦ <i>avec l’inf</i>. PLAT. <i>Leg. 678</i> d, difficulté de, <i>etc. ; avec</i> τοῦ μή <i>et l’inf. :</i> ἀπ. τοῦ μὴ ἡσυχάζειν, THC. <i>2, 49,</i> impossibilité de rester tranquille ;<br><b>      4</b> anxiété (d’un malade) HPC. <i>1153</i> b, <i>etc. ;</i><br><b>      5</b> embarras, incertitude, <i>particul. dans une recherche, dans une discussion :</i> ἀπορίαν ἀπορεῖν, PLAT. <i>Prot. 324</i> d, être dans le doute (περί τι, PLAT. <i>Epin. 974</i> c ; περί τινος, ARSTT. <i>Pol. 3, 15, 14,</i> au sujet de qqe ch.) ; ἀπορίαν λύειν, DS. <i>1, 37,</i> résoudre une difficulté ;<br><b>   III</b> le fait de ne pas se procurer qqe ch., non-acquisition, PLAT. <i>Men. 78</i> e.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -ίη, HDT. <i>1, 24, etc. ;</i> HPC. <i>l. c., etc</i>.<br><span><b>Étym</b>. ἄπορος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απορια - ἀπορία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G641":"<h1>aporrhipto</h1>\n<p>Strong n° 641 <i>Prononciation [ap-or-hrip'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>jeter au loin, jeter par terre, se précipiter</li>\n<li>se jeter par terre ou à l'eau</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·ρρίπτω</b> <span>(<i>f</i>. ίψω, <i>ao</i>. ἀπέρριψα)</span> jeter loin de soi, <i>d’où :</i><br><b>      1</b> rejeter : <i>fig</i>. μῆνιν, μηνιθμόν, IL. <i>9, 517 ; 16, 282,</i> déposer <i>ou</i> oublier sa colère ; <i>en mauv. part,</i> jeter de côté, jeter au rebut, HDT. <i>1, 32 ;</i> ESCHL. <i>Eum. 215 ;</i> ἀπερριμμένος, DÉM. <i>242, 3 ;</i> HDN <i>4, 12, 4,</i> mis de côté, jeté au rebut ;<br><b>      2</b> lancer : τι ἔς τινα, HDT. <i>1, 153, etc</i>. des paroles contre qqn ;<br><b>      3</b> laisser tomber : ἔπος, HDT. <i>6, 69 ;</i> PD. <i>O. 9, 39,</i> une parole ;<br><b>      4</b> jeter au loin, <i>d’où</i> expulser, bannir, ESCHL. <i>Ch. 914 ;</i> γῆς, SOPH. <i>Aj. 1019,</i> d’un pays ; ἐκ θεῶν, XÉN. <i>Mem. 2, 1, 31,</i> d’entre les dieux.<br><span><b><span class=\"arrow\"></span></b> <i>Poét</i>. ἀπορίπτω, ANACR. <i>39 ; ao. 3 sg</i>. ἀπέριψεν, PD. <i>P. 6, 37</i>.<br><span><b>Étym</b>. ἀ. ῥίπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-ρριπτω - ἀπορρίπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G642":"<h1>aporphanizo</h1>\n<p>Strong n° 642 <i>Prononciation [ap-or-fan-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>priver de parent ou de parents, séparer, être orphelin</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπ·ορφανίζω</b> <span>[φᾰ]</span> (<i>seul. ao. pass</i>. ἀπωρφανίσθην, NT. ; <i>part. pf. pass</i>. ἀπωρφανισμένος, ESCHL. <i>Ch. 249</i>) rendre orphelin, <i>d’où, en gén.,</i> priver de.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απ-ορφανιζω - ἀπορφανίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G643":"<h1>aposkeuazo</h1>\n<p>Strong n° 643 <i>Prononciation [ap-osk-yoo-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>transporter marchandises et biens</li>\n<li>emballer et transporter</li>\n<li>préparer ses biens pour les déménager, faire ses bagages</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·σκευάζω</b>, démolir, enlever : ὀροφήν, LYCURG. <i>166, 9,</i> un toit ;<br><b><i>Moy.</i></b> :<br><b>      1</b> emporter ses bagages pour les déposer (en lieu sûr) POL. <i>2, 26, 6 ;</i><br><b>      2</b> se défaire <i>ou</i> se débarrasser de, <i>acc</i>. LUC. <i>Tyr. 1, etc. ;</i> HDN <i>4, 13, 9, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-σκευαζω - ἀποσκευάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G644":"<h1>aposkiasma</h1>\n<p>Strong n° 644 <i>Prononciation [ap-os-kee'-as-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une ombre portée par un objet sur un autre, obscurcissement, assombrissement (terme astronomique)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀποσκίασμα, ατος (τὸ)</b> ombre projetée, BAS. <i>1, 7</i> d.<br><span><b>Étym</b>. ἀποσκιάζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-σκιασμα - ἀποσκίασμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G645":"<h1>apospao</h1>\n<p>Strong n° 645 <i>Prononciation [ap-os-pah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tirer, déchirer, tirer dehors</li>\n<li>attirer, entraîner</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·σπάω-ῶ :<br>   I <i>tr</i>.<br>      1</b> tirer violemment, <i>avec un seul rég. à l’acc. :</i> τινα, HDT. <i>6, 91,</i> entraîner qqn ; θύρας, πύλας, HDT. <i>1, 17 ; 3, 159,</i> ouvrir une porte avec force <i>ou</i> violence ; <i>avec double rég. :</i> τινα ἀπὸ γυναικὸς καὶ τέκνων, HDT. <i>3, 1,</i> arracher qqn à sa femme et à ses enfants ; τινα ἐκ χερῶν, EUR. <i>Hec. 277,</i> arracher une personne aux mains d’une autre ; <i>fig</i>. τινά τι, SOPH. <i>O.C. 866,</i> enlever qqe ch. (l’espérance, <i>etc</i>.) à qqn ; <i>avec un gén. d’instrum</i>. ἀπ. τινα κόμης, ESCHL. <i>Suppl. 909,</i> tirer qqn par les cheveux ; <i>au pass</i>. ἀποσπᾶσθαί τινος, être séparé violemment de qqe ch. PD. <i>P. 9, 34 ; ou</i> de qqn, EUR. <i>Alc. 287, etc. ;</i> ἐξ ἱροῦ, HDT. <i>1, 160 ;</i> ἀπὸ τῶν ἱερῶν, THC. <i>3, 81,</i> être entraîné hors d’un temple, d’un sacrifice ;<br><b>      2</b> <i>p. ext</i>. tirailler en tous sens, <i>d’où au pass</i>. se désunir, marcher en désordre, <i>en parl. d’une armée,</i> THC. <i>7, 80 ;</i><br><b>   II</b> <i>intr. (s.-e</i>. ἑαυτόν) s’arracher, se séparer avec effort de, XÉN. <i>An. 1, 5, 3 (conj</i>.) ; LUC. <i>Ic. 11, etc. ;</i><br><b><i>Moy.</i></b> attirer l’ennemi à soi loin de (tout secours maritime) PLUT. <i>Pomp. 76</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-σπαω - ἀποσπάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G646":"<h1>apostasia</h1>\n<p>Strong n° 646 <i>Prononciation [ap-os-tas-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>action de s'éloigner de, défection, désertion</li>\n<li>apostasie</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀποστασία, ας (ἡ)</b> <span>[τᾰ]</span> défection, abandon d’un parti, DH. <i>7, 1 ;</i> PLUT. <i>Galb. 1 ; particul</i>. apostasie, SPT. <i>3Reg. 21, 13, etc</i>.<br><span><b>Étym</b>. ἀφίστημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-στασια - ἀποστασία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>2 Thessanoniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G647":"<h1>apostasion</h1>\n<p>Strong n° 647 <i>Prononciation [ap-os-tas'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>divorce, répudiation</li>\n<li>une lettre de divorce, billet de divorce</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>*ἀποστάσιον (τὸ)</b> <span>[τᾰ]</span> éloignement, <i>seul. dans les loc</i>. ἀποστασίου δίκη, DÉM. <i>790, 2 ; 940, 15,</i> action judiciaire contre un affranchi qui abandonne son patron ; <i>et</i> ἀποστασίου βιϐλίον, SPT. <i>Deut. 24, 3 ; Esaï. 50, 1 ;</i> NT. <i>Matth. 19, 7 ; Marc. 10, 4 ; ou abs</i>. ἀποστάσιον, NT. <i>Matth. 5, 31,</i> déclaration de divorce.<br><span><b>Étym</b>. ἀφίστημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-στασιον - ἀποστάσιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G648":"<h1>apostegazo</h1>\n<p>Strong n° 648 <i>Prononciation [ap-os-teg-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>découvrir, enlever une toiture</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·στεγάζω :<br>      1</b> ôter le toit, découvrir, STR. <i>198 ;</i> NT. ; <i>d’où</i> ouvrir, SOTAD. (ATH. <i>621</i> b) ;<br><b>      2</b> recouvrir, TH. <i>C.P. 5, 6, 5</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-στεγαζω - ἀποστεγάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G649":"<h1>apostello</h1>\n<p>Strong n° 649 <i>Prononciation [ap-os-tel'-lo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ordonner à quelqu'un d'aller vers un lieu défini</li>\n<li>envoyer au loin, congédier\n<ol type=\"a\">\n<li>autoriser quelqu'un à partir, lui donner sa liberté</li>\n<li>ordonner à quelqu'un de partir, congédier</li>\n<li>conduire au loin</li>\n</ol>\n</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·στέλλω :<br>      1</b> envoyer : παρά τινα, HDT. <i>5, 32 ;</i> ὥς τινα, CALL. <i>fr. 89,</i> auprès de qqn ; <i>d’où en gén.,</i> envoyer : πρεσϐείαν, THC. <i>3, 28 ;</i> ἀποικίην, HDT. <i>4, 150 ;</i> ἀγγέλους, XÉN. <i>An. 2, 1, 5,</i> une ambassade, une colonie, des messagers ; ἐς τοὺς Πέρσας, HDT. <i>1, 123,</i> envoyer (qqe ch.) aux Perses ; τινὰ ἐς τὰ Τροίας πεδία, SOPH. <i>Ph. 1297,</i> envoyer qqn dans les plaines de Troie ; βέλος, PHIL. BYZ. <i>Bel. 68,</i> lancer un trait ; <i>au pass. avec l’inf</i>. οἱ ἀποσταλέντες στρατεύεσθαι, HDT. <i>3, 26,</i> ceux qui avaient été envoyés pour l’expédition ;<br><b>      2</b> faire partir, renvoyer, <i>acc</i>. SOPH. <i>Ph. 125 ; en mauv. part,</i> chasser, bannir : τινὰ γῆς, χθονός, SOPH. <i>El. 71 ;</i> EUR. <i>Med. 281 ;</i> ἔξω χθονός, EUR. <i>Ph. 485 ;</i> ἐκ τῆς πόλεως, PLAT. <i>Rsp. 607</i> b, chasser qqn d’un pays, de la cité ; <i>au pass</i>. être chassé, banni, EUR. <i>Ph. 319 ; p. ext</i>. s’éloigner, SOPH. <i>O.R. 115 ;</i> EUR. <i>Suppl. 582, etc. ;</i><br><b>      3</b> retirer : ἱμάτια, AR. <i>Lys. 1084,</i> des vêtements ; θάλατταν, THC. <i>3, 89,</i> causer un retrait de la mer ;<br><b>      4</b> déléguer, confier, ESCHL. <i>Ag. 908</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-στελλω - ἀποστέλλω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n131 fois dans 129 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (21)</li>\n<li>Marc (20)</li>\n<li>Luc (26)</li>\n<li>Jean (28)</li>\n<li>Actes (24)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n<li>1 Jean (3)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G650":"<h1>apostereo</h1>\n<p>Strong n° 650 <i>Prononciation [ap-os-ter-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>frauder, voler, dépouiller, priver</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·στερέω-ῶ :<br>      1</b> priver de, dépouiller de : <i>avec le gén. de la chose :</i> τινά τινος ἀπ. HDT. <i>4, 92, etc. ;</i> ATT. (ESCHL. <i>Pr. 681 ;</i> XÉN. <i>Mem. 1, 2, 63, etc</i>.) dépouiller qqn de qqe ch. (de sa fortune, de la royauté, de la vie, <i>etc</i>.) ; <i>d’où au pass</i>. être privé de, <i>gén</i>. HDT. <i>3, 130 ;</i> SOPH. <i>El. 813 ;</i> THC. <i>3, 42, etc. ; avec double acc</i>. τινά τι, XÉN. <i>An. 7, 6, 9 ; ou avec le gén. de pers. et l’acc. de chose :</i> τινός τι, XÉN. <i>Hell. 4, 1, 20,</i> enlever qqe ch. à qqn ; <i>avec un seul rég. de chose à l’acc. :</i> ESCHL. <i>Pr. 777 ;</i> SOPH. <i>O.R. 323 ;</i> DÉM. <i>528, 16, etc. ;</i> ἀπ. γάμον, ESCHL. <i>Suppl. 1063,</i> détourner un mariage ; <i>au pass</i>. être dépossédé <i>ou</i> privé de, <i>acc</i>. XÉN. <i>Cyr. 6, 1, 12 ;</i> PLAT. <i>Theæt. 201</i> b ;<br><b>      2</b> faire défaut, manquer à : τὸ σαφές μ' ἀποστερεῖ, EUR. <i>Hel. 577,</i> la certitude me fait défaut.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. pass</i>. ἀποστερηθήσομαι, LYS. DÉM. ISOCR. <i>Fut. moy. au sens pass</i>. ἀποστερήσομαι, EUR. <i>H.f. 137 ;</i> THC. <i>6, 91 ;</i> DÉM. <i>765, 14, et</i> ἀποστεροῦμαι, AND. <i>19, 26</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-στερεω - ἀποστερέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>1 Corinthiens (3)</li>\n<li>1 Timothée (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G651":"<h1>apostole</h1>\n<p>Strong n° 651 <i>Prononciation [ap-os-tol-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un envoyé au loin\n<ol type=\"a\">\n<li>envoi d'une flotte</li>\n<li>de consuls avec une armée, une expédition</li>\n</ol>\n</li>\n<li>un renvoi, libérer</li>\n<li>une chose envoyée, des dons</li>\n<li>dans le N.T, le rôle et la fonction des apôtres de Christ, apostolat.</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀποστολή, ῆς (ἡ) :<br>   I</b> <i>act. :</i><br><b>      1</b> éloignement, EUR. <i>I.A. 688 ;</i><br><b>      2</b> mission, EUR. <i>Ph. 1043, etc. ;</i><br><b>      3</b> envoi d’une flotte, THC. <i>8, 9 ;</i><br><b>      4</b> envoi d’un tribut, tribut, JUL. <i>397</i> c ;<br><b>      5</b> action de lancer (des traits), PHIL. BYZ. <i>Bel. 69 ;</i><br><b>   II</b> <i>pass. :</i><br><b>      1</b> départ (de troupes), THC. <i>8, 8 ;</i><br><b>      2</b> apostolat, SPT. <i>1Reg. 9, 16 ; 1 Macc. 2, 18 ; 2 Macc. 3, 2 ;</i> NT. <i>Ap. 1, 25 ; Rom. 1, 5</i>.<br><span><b>Étym</b>. ἀποστέλλω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-στολη - ἀποστολή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G652":"<h1>apostolos</h1>\n<p>Strong n° 652 <i>Prononciation [ap-os'-tol-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>apôtre = « envoyé en avant, messager, ambassadeur »\n<ol>\n<li>un délégué, messager, celui qui est envoyé avec des ordres\n<ol type=\"a\">\n<li>spécifiquement appliqué aux 12 apôtres de Christ</li>\n<li>dans un sens plus étendu, les enseignants Chrétiens éminents\n<ol>\n<li>Paul</li>\n<li>Timothée et Silvain</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπόστολος, ος, ον :<br>   I</b> <i>adj</i>. envoyé au loin : ἀπ. πλοῖον, PLAT. <i>Ep. 346</i> a ; <i>ou subst</i>. τὸ ἀπ. Ps.-PLUT. <i>V. Hom. 19,</i> vaisseau marchand ;<br><b>   II</b> <i>subst</i>. ὁ ἀπ. :<br><b>      1</b> envoyé, député, HDT. <i>1, 21, etc. ; particul</i>. envoyé de Dieu, <i>en parl. de J.C</i>. NT. <i>Hebr. 3, 1 ; d’ord</i>. apôtre, NT. <i>Luc. 6, 3 ; Joh. 13, 16 ; particul</i>. l’apôtre Paul, CLÉM. <i>1, 269</i> b ; <i>2, 57</i> c <i>Migne, etc. ; d’où</i> οἱ ἀπόστολοι, ORIG. <i>1, 1413 ; 4, 61 Migne ; et collectiv. au sg</i>. ὁ ἀπόστολος, CLÉM. <i>2, 417 ;</i> BAS. <i>4, 188, etc. Migne,</i> les Épîtres du Nouveau Testament ;<br><b>      2</b> envoi d’une expédition, <i>particul</i>. expédition navale, LYS. <i>153, 40 ;</i> ἀπόστολον ἀφιέναι, ἀποστέλλειν, envoyer une flotte, DÉM. <i>30, 5 ; 252, 7, etc. ou</i> une colonie, DH. <i>9, 39</i>.<br><span><b>Étym</b>. ἀποστέλλω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αποστολος - ἀπόστολος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n81 fois dans 80 versets de 21 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (6)</li>\n<li>Jean (1)</li>\n<li>Actes (30)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (10)</li>\n<li>2 Corinthiens (6)</li>\n<li>Galates (3)</li>\n<li>Ephésiens (4)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Timothée (2)</li>\n<li>2 Timothée (2)</li>\n<li>Tite (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (2)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G653":"<h1>apostomatizo</h1>\n<p>Strong n° 653 <i>Prononciation [ap-os-tom-at-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>réciter de mémoire\n<ol type=\"a\">\n<li>répéter à un élève pour qu'il enregistre dans sa mémoire</li>\n</ol>\n</li>\n<li>exercer par des questions, catéchiser, attirer les réponses</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·στοματίζω</b> <span>(<i>f</i>. -ιῶ)</span> <span>[μᾰ]</span><br><b>      1</b> réciter <i>ou</i> débiter de vive voix, ATH. <i>559</i> d ; <i>en parl. d’une réponse d’oracle,</i> PLUT. <i>Thes. 24 ; particul</i>. réciter une leçon pour l’apprendre à qqn, dicter une leçon, PLAT. <i>Euthyd. 277</i> a ; ARSTT. <i>Soph. el. 4, 1 ;</i><br><b>      2</b> provoquer à parler, NT. <i>Luc. 11, 53</i>.<br><span><b>Étym</b>. ἀ. στόμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-στοματιζω - ἀποστοματίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G654":"<h1>apostrepho</h1>\n<p>Strong n° 654 <i>Prononciation [ap-os-tref'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tourner, détourner\n<ol type=\"a\">\n<li>enlever quelque chose à quelqu'un</li>\n<li>le détourner de l'allégeance à quelqu'un</li>\n</ol>\n</li>\n<li>retourner, remettre, rapporter, ramener\n<ol type=\"a\">\n<li>remettre une épée au fourreau</li>\n<li>Judas rapportant l'argent au temple</li>\n</ol>\n</li>\n<li>déserter</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·στρέφω</b> <span>(<i>f</i>. έψω, <i>ao</i>. ἀπέστρεψα, <i>pf. inus</i>.)</span><br><b>   I <i>tr</i>.<br>      1</b> tourner en sens contraire, retourner : νῆας, OD. <i>3, 162,</i> détourner des vaisseaux ; ἅρματα ὡς εἰς φυγήν, XÉN. <i>Cyr. 6, 2, 13,</i> détourner des chars comme pour fuir ; αἱ νῆες ἀπεστράφατο (<i>ion</i>.) τοὺς ἐμϐόλους, HDT. <i>1, 166,</i> les vaisseaux avaient leurs éperons retournés, <i>càd</i>. tordus, faussés : ἀποστρέφειν πάλιν, SOPH. <i>O.C. 1403,</i> ramener en arrière ; <i>particul</i>. ἀπ. χεῖρας, OD. <i>22, 173, 190 ;</i> SOPH. AR. DÉM. amener les mains en arrière (pour les attacher derrière le dos) ;<br><b>      2</b> faire se retourner : τινά, THC. <i>4, 97 ; 5, 75,</i> renvoyer qqn chez lui ; <i>avec idée d’hostilité :</i> Ἀχαιοὺς ἀπ. IL. <i>15, 62,</i> faire fuir les Grecs ;<br><b>      3</b> faire revenir, rappeler : ἐξ ἰσθμοῦ, XÉN. <i>An. 2, 6, 3,</i> de l’isthme ;<br><b>      4</b> détourner (un danger, une guerre, <i>etc</i>.) ESCHL. <i>Ag. 850 ;</i> AR. <i>Nub. 776 ;</i> DH. <i>10, 2, etc. ;</i> ἀπ. τινά τινος, XÉN. <i>Hipp. 1, 12,</i> dissuader qqn de qqe ch. ;<br><b>   II <i>intr</i>.<br>      1</b> se détourner, HDT. <i>8, 87 ;</i> XÉN. <i>Hell. 3, 4, 12 ; en parl. d’un fleuve,</i> HDT. <i>4, 52 ;</i><br><b>      2</b> retourner sur ses pas, se retirer, HDT. <i>4, 43 ;</i> THC. <i>6, 65 ;</i> SOPH. <i>O.C. 1403 ;</i><br><b><i>Moy.</i></b> <span>(<i>f</i>. -στρέψομαι ; <i>ao. pass</i>. ἀπεστράφην, <i>au sens moy</i>.)</span><br><b>      1</b> se détourner, faire volte-face, s’enfuir, XÉN. <i>Cyr. 6, 2, 17 ;</i> PLAT. <i>Rsp. 405</i> c ; POL. <i>5, 85, 4, etc. ;</i> ἀποστραφῆναί τινος, XÉN. <i>Hell. 4, 8, 4,</i> abandonner qqn ;<br><b>      2</b> <i>particul</i>. se détourner avec horreur <i>ou</i> dégoût de, <i>acc</i>. SOPH. <i>O.C. 1272 ;</i> EUR. <i>I.T. 801, etc. ;</i> λόγοι ἀπεστραμμένοι, HDT. <i>7, 160,</i> paroles hostiles.<br><span><b><span class=\"arrow\"></span></b> <i>Act. ao. itér. 3 sg. épq</i>. ἀποστρέψασκε, IL. <i>22, 197. Ao. subj. 3 sg. épq</i>. ἀποστρέψῃσι, IL. <i>15, 62. Pass. pl.q.pf. 3 pl. ion</i>. ἀπεστράφατο, HDT. <i>1, 166. Moy. fut. réc</i>. ἀποστραφήσομαι, SPT. ; <i>ao. réc</i>. ἀπεστρεψάμην, SPT.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-στρεφω - ἀποστρέφω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 10 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (2)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>2 Timothée (2)</li>\n<li>Tite (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G655":"<h1>apostugeo</h1>\n<p>Strong n° 655 <i>Prononciation [ap-os-toog-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>aversion, ne pas aimer, détester, avoir horreur de, éprouver une farouche horreur, abhorrer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·στυγέω-ῶ</b> <span>[ῠ]</span> s’éloigner avec horreur de, repousser avec horreur, abhorrer, <i>acc</i>. HDT. <i>2, 47 ;</i> SOPH. <i>O.C. 186, 692 ;</i> EUR. <i>Ion 488 ; gén</i>. PLUT. <i>Pyrrh. 21 ;</i> JOS. ; <i>avec une prop. inf</i>. HDT. <i>6, 129</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao</i>. ἀπεστύγησα, SOPH. <i>O.C. 692 ;</i> ἀπέστυξα, OPP. <i>H. 4, 370. Ao.2</i> ἀπέστυγον <span>[ῠ]</span> NIC. <i>Al. 406 ;</i> CALL. <i>Del. 223. Pf. au sens d’un prés</i>. ἀπεστύγηκα, HDT. <i>2, 47</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-στυγεω - ἀποστυγέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (2)</li>\n</ul>\n</td></tr>\n</table>","G656":"<h1>aposunagogos</h1>\n<p>Strong n° 656 <i>Prononciation [ap-os-oon-ag'-o-gos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>exclu de l'assemblée des Israélites, excommunié</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·συνάγωγος, ος, ον</b> <span>[ῠᾰ]</span> exclu de la synagogue, NT. <i>Joh. 9, 22</i>.<br><span><b>Étym</b>. ἀ. συναγωγή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-συναγωγος - ἀποσυνάγωγος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Jean (3)</li>\n</ul>\n</td></tr>\n</table>","G657":"<h1>apotassomai</h1>\n<p>Strong n° 657 <i>Prononciation [ap-ot-as'-som-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre à part, séparer\n<ol type=\"a\">\n<li>se séparer, s'éloigner de quelqu'un\n<ol>\n<li>prendre congé, adieu d'un invité</li>\n</ol>\n</li>\n<li>renoncer à, abandonner</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·τάσσω</b>, <i>att</i>. <b>-τάττω :<br>      1</b> poster à part, détacher dans un poste, POL. <i>6, 35, 3 ; au pass</i>. être détaché dans un poste, XÉN. <i>Hell. 5, 2, 40 ;</i><br><b>      2</b> assigner : χώραν τινί, PLAT. <i>Theæt. 153</i> e, une place à qqe ch. ; <i>cf</i>. PLUT. <i>M. 120</i> b ; ἀποτεταγμένη ἀρχή, ARSTT. <i>Pol. 6, 8, 13,</i> charge assignée à qqn ;<br><b><i>Moy.</i></b> se séparer de, renoncer à, <i>dat</i>. NT. <i>Ap. 18, 18 ; Luc. 9, 61 ;</i> JOS. <i>A.J. 11, 8, 6</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-τασσομαι - ἀποτάσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Actes (2)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G658":"<h1>apoteleo</h1>\n<p>Strong n° 658 <i>Prononciation [ap-ot-el-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>parfaire, amener au bout, mener à son terme</li>\n<li>accomplir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·τελέω-ῶ</b>, mener à terme, <i>d’où :</i><br><b>      1</b> achever, accomplir (une œuvre, une entreprise) <i>acc</i>. HDT. <i>5, 92 ;</i> ATT. ; ἀπ. τὰς ἐπιθυμίας, PLAT. <i>Gorg. 503</i> d, satisfaire ses désirs ; ἀπ. τὰ προσταχθέντα, PLAT. <i>Leg. 823</i> d, exécuter les ordres donnés ; τὰ προσήκοντα, XÉN. <i>Cyr. 5, 1, 14 ;</i> PLAT. <i>Criti. 108</i> d, <i>ou</i> τὰ καθήκοντα, XÉN. <i>Cyr. 1, 2, 5,</i> remplir ses devoirs ; ἀνὴρ ἀποτετελεσμένος, XÉN. <i>Hipp. 7, 4, etc</i>. un homme accompli ;<br><b>      2</b> <i>avec un attrib</i>. produire, rendre : ἀμείνους ἐκ χειρόνων, PLAT. <i>Pol. 297</i> b, rendre (des hommes) meilleurs de pires qu’ils étaient ; τὴν πόλιν εὐδαίμονα, PLAT. <i>Leg. 718</i> b, rendre la cité heureuse ; τύραννος ἀντὶ προστάτου ἀποτετελεσμένος, PLAT. <i>Rsp. 566</i> d, devenu tyran de chef qu’il était ;<br><b>      3</b> acquitter, payer (une dette) : εὐχὰς ἀπ. HDT. <i>2, 65,</i> acquitter un vœu ; ἀπ. ἀπαρχήν, PLAT. <i>Leg. 806</i> e ; χαριστήρια, XÉN. <i>Cyr. 3, 2, 18,</i> offrir (à une divinité) des prémices, un sacrifice d’action de grâces.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-τελεω - ἀποτελέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G659":"<h1>apotithemi</h1>\n<p>Strong n° 659 <i>Prononciation [ap-ot-eeth'-ay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>poser de côté ou au loin, se débarrasser de</li></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·τίθημι :<br>      1</b> déposer : τι, IL. <i>16, 254,</i> qqe ch. ; ἀπ. εἰς δεσμωτήριον, LYCURG. <i>164, 2,</i> mettre en prison ;<br><b>      2</b> exposer (un enfant), PLAT. <i>Theæt. 161</i> a ;<br><b><i>Moy</i>. ἀποτίθεμαι</b> <span>(<i>f</i>. ἀποθήσομαι, <i>ao.1</i> ἀπεθηκάμην, <i>ao.2</i> ἀπεθέμην)</span><br><b>   I</b> mettre à bas, <i>d’où :</i><br><b>      1</b> déposer : τεύχεα, IL. <i>3, 89 ;</i> στολήν, HDT. <i>4, 78,</i> ses armes, sa robe ; <i>fig</i>. ἀρχήν, POL. <i>5, 1 ;</i> PLUT. <i>Pomp. 23,</i> déposer une magistrature ; ὀργήν, PLUT. <i>Cor. 19,</i> laisser tomber <i>ou</i> se calmer sa colère ;<br><b>      2</b> exposer (un enfant) ARSTT. <i>Pol. 7, 16, 15 ;</i><br><b>      3</b> déposer, déférer, transporter : εἰς φυλακήν, POL. <i>24, 8, 8 ;</i> DS. <i>4, 46 et 49,</i> mettre en prison ;<br><b>   II</b> mettre de côté, <i>d’où :</i><br><b>      1</b> remettre, différer : εἰσαῦθις, EUR. <i>I.T. 376,</i> remettre à une autre fois ; <i>cf</i>. XÉN. <i>Conv. 2, 7 ;</i> PLAT. <i>Gorg. 449</i> b ;<br><b>      2</b> mettre en réserve, réserver, PLAT. <i>Leg. 837</i> c, <i>etc. ;</i><br><b>   III</b> mettre hors de : κόλπων, CALL. <i>Dian. 25,</i> hors de son sein, enfanter ;<br><b>   IV</b> écarter de soi : ἐνιπήν, IL. <i>5, 492,</i> un reproche ; νεῖκος, PD. <i>O. 11, 42,</i> une querelle.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-τιθημι - ἀποτίθημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 7 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>Ephésiens (2)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G660":"<h1>apotinasso</h1>\n<p>Strong n° 660 <i>Prononciation [ap-ot-in-as'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>secouer pour faire tomber</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·τινάσσω</b> <span>[ῐ]</span> faire tomber en secouant, EUR. <i>Bacch. 253 ;</i><br><b><i>Moy.</i></b> <i>m. sign</i>. GAL. ; <i>fig</i>. SPT. <i>1Reg. 10, 2</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αποτινασσω - ἀποτινάσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G661":"<h1>apotino</h1>\n<p>Strong n° 661 <i>Prononciation [ap-ot-ee'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>payer( terme juridique), rembourser, dédommager</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·τίνω</b> <span>[<i>prés. épq</i>. ῑ, <i>att</i>. ῐ ; <i>fut</i>. ῑ]</span><br><b>      1</b> payer en retour : μισθόν, XÉN. une solde ; <i>fig</i>. τιμήν τινι, IL. <i>3, 286,</i> honorer qqn en retour ; εὐεργεσίας ἀπ. OD. <i>22, 235,</i> témoigner sa reconnaissance par des bienfaits ; <i>particul</i>. payer en échange d’une faute : τίσιν ἀπ. ORACL. (HDT. <i>6, 56</i>) acquitter sa dette, expier une faute ; ἀπ. ζημίην, HDT. <i>2, 65,</i> payer une amende ; <i>abs</i>. παθεῖν ἢ ἀποτῖσαι, DÉM. <i>529, 23 (loi</i>) ; PLAT. <i>Pol. 299</i> a, <i>etc</i>. être puni d’une peine corporelle <i>ou</i> d’une amende ;<br><b>      2</b> <i>p. suite, avec l’acc. de la chose pour laquelle on paie, d’où</i> payer pour, expier : ὑπερϐασίην ἀπ. OD. <i>13, 193,</i> expier son insolence ; αἷμα, ESCHL. <i>Ag. 1338 ;</i> φόνον, EUR. <i>I.T. 338,</i> expier le sang répandu, un meurtre, <i>etc. ;</i><br><b><i>Moy.</i></b> faire payer, <i>avec l’acc. de la chose :</i> ποινήν τινος, OD. <i>23, 312,</i> faire payer la rançon (le meurtre) de qqn ; <i>avec l’acc. de la chose pour laquelle on paie :</i> ἀπ. βίας τινός, OD. <i>11, 118 ; 16, 255, ou</i> βίας τινί, OD. <i>3, 216,</i> faire payer à qqn ses violences, l’en punir ; <i>avec l’acc. de la pers. :</i> ἀπ. τινά, OD. <i>13, 386 ; 24, 480 ;</i> XÉN. <i>Cyr. 5, 4, 35,</i> punir qqn, tirer vengeance de qqn ; <i>avec double acc. :</i> δίκην ἐχθροὺς ἀπ. EUR. <i>Her. 852, 882,</i> tirer vengeance de ses ennemis.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. inf. épq</i>. ἀποτινέμεν, IL. <i>3, 286 ; fut. inf. épq</i>. ἀποτισέμεν, IL. <i>21, 399</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-τινω - ἀποτίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philémon (1)</li>\n</ul>\n</td></tr>\n</table>","G662":"<h1>apotolmao</h1>\n<p>Strong n° 662 <i>Prononciation [ap-ot-ol-mah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>assumer avec hardiesse, faire le hardi, pousser la hardiesse jusqu'à, oser</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·τολμάω-ῶ</b>, affronter le danger, THC. <i>7, 67 ; avec l’inf</i>. oser, LYS. <i>110, 41 ;</i> τὰ ἀποτετολμημένα, PLAT. <i>Rsp. 503</i> b, ce qu’on ose déclarer ; ἐλευθερία λίαν ἀποτετολμημένη, PLAT. <i>Leg. 701</i> b, liberté trop osée.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-τολμαω - ἀποτολμάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT).\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G663":"<h1>apotomia</h1>\n<p>Strong n° 663 <i>Prononciation [ap-ot-om-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sévérité, rudesse, rigueur, caractère tranchant</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀποτομία, ας (ἡ)</b> caractère incisif <i>ou</i> tranchant, dureté, DS. <i>12, 16 ;</i> PLUT. <i>M. 13</i> d, <i>etc</i>.<br><span><b>Étym</b>. ἀπότομος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-τομια - ἀποτομία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT).\n<ul>\n<li>Romains (2)</li>\n</ul>\n</td></tr>\n</table>","G664":"<h1>apotomos</h1>\n<p>Strong n° 664 <i>Prononciation [ap-ot-om'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>brusquement, précipitamment</li>\n<li>sévèrement, avec rigueur, d'une manière tranchante, durement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀποτόμως</b>, <i>adv. :</i><br><b>      1</b> précisément, absolument, ISOCR. <i>126</i> b ; DÉM. <i>1402, 16 ;</i><br><b>      2</b> d’une manière tranchante, durement, CIC. <i>Att. 12, 6</i>.<br><span><b>Étym</b>. ἀπότομος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αποτομως - ἀποτόμως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G665":"<h1>apotrepo</h1>\n<p>Strong n° 665 <i>Prononciation [ap-ot-rep'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se détourner de</li>\n<li>fuir, éviter, s'éloigner</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·τρέπω :<br>      1</b> détourner, écarter : τινά, IL. <i>11, 758 ; 15, 276,</i> qqn ; ἔγχεος ὁρμήν, HÉS. <i>Sc. 456,</i> détourner l’essor d’une javeline ; <i>fig</i>. βλάϐην, ξυμφοράν, PLAT. <i>Gorg. 509</i> b, <i>etc</i>. détourner un mal, un malheur ; ἐπί τινι ἔγχος ἀφ. SOPH. <i>Tr. 1012,</i> détourner sa lance d’un ennemi sur un autre ;<br><b>      2</b> détourner par la crainte <i>ou</i> la persuasion, dissuader : τινὰ ἐπέεσσιν, IL. <i>20, 256,</i> dissuader qqn par ses paroles ; τινά τινος, IL. <i>12, 249 ;</i> ATT. détourner qqn de qqe ch. ; <i>avec l’inf</i>. ESCHL. <i>Suppl. 900 ;</i> XÉN. <i>Mem. 4, 7, 5 et 6 ;</i> DÉM. <i>1397, 2, etc. ; avec</i> τὸ μή <i>et l’inf</i>. HDT. <i>1, 105 ; avec</i> μὴ οὐχί <i>et l’inf</i>. LUC. <i>D. deor. 5, 5,</i> détourner qqn de, <i>etc. ;</i><br><b><i>Moy.</i></b> <span>(<i>f</i>. ἀποτρέψομαι, <i>f. 2</i> ἀποτραπήσομαι, <i>ao.2</i> ἀπετραπόμην)</span><br><b>   I <i>intr</i>.<br>      1</b> se détourner : εἴς τι, LUC. <i>Tox. 52, ou</i> πρός τι, PLUT. <i>Fab. 19, Rom. 7,</i> d’une chose vers une autre ; <i>abs</i>. se détourner avec indifférence, IL. <i>12, 329 ; fig</i>. s’abstenir de, cesser : τοῦ ἐρωτήματος, XÉN. <i>Œc. 15, 13,</i> de questionner ; <i>avec un inf</i>. EUR. <i>Or. 410 ;</i> DÉM. <i>1434, 12 ;</i> ANT. <i>133, 17,</i> cesser de, <i>etc. ; abs</i>. THC. <i>3, 11, etc. ;</i><br><b>      2</b> se détourner, s’éloigner, IL. <i>10, 200 ;</i> ἐκ κινδύνων, THC. <i>2, 40,</i> fuir loin du danger ; <i>abs</i>. s’en retourner, THC. <i>3, 24 ; 5, 13 ;</i> XÉN. <i>Hell. 7, 2, 13 ;</i><br><b>   II <i>tr.</i></b> détourner de soi (un malheur, <i>etc.) acc</i>. ESCHL. <i>Sept. 1060 ;</i> EUR. <i>I.A. 336 ;</i> PLUT. <i>Cleom. 9</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-τρεπω - ἀποτρέπω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G666":"<h1>apousia</h1>\n<p>Strong n° 666 <i>Prononciation [ap-oo-see'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>absence, être absent</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπουσία, ας (ἡ) :<br>      1</b> absence, ESCHL. <i>Ag. 1259 ;</i> THC. <i>1, 70, etc. ;</i><br><b>      2</b> manque, défaut de, perte, ARSTT. <i>Meteor. 4, 6, 10,</i> DS. <i>3, 14 ;</i><br><b>      3</b> <i>particul</i>. perte séminale, PLUT. <i>M. 364</i> d.<br><span><b>Étym</b>. <i>part. prés. de</i> ἄπειμι¹.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απουσια - ἀπουσία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G667":"<h1>apophero</h1>\n<p>Strong n° 667 <i>Prononciation [ap-of-er'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être emmené ou transporté ailleurs, entraîner</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·φέρω</b> <span>(<i>f</i>. ἀποίσω, <i>ao.1</i> ἀπήνεγκα, <i>ao.2</i> ἀπήνεγκον, <i>etc</i>.)</span><br><b>   I <i>tr</i>.<br>      1</b> emporter (dans les bras, sur une voiture, <i>etc</i>.) IL. <i>15, 20, etc. ;</i> OD. <i>16, 360, etc. ;</i> ἀπό τινος, IL. <i>5, 257,</i> de chez qqn ; τεθνεὼς ἐκ δεσμωτηρίου ἀπηνέχθη, LYS. <i>121, 34,</i> il fut emporté mort de la prison ; <i>par anal. en parl. du vent, d’exhalaisons,</i> IL. <i>14, 255 ;</i> ὑπ' ἀνέμου ἐς γῆν ἀπενειχθείς (<i>ion</i>.) HDT. <i>2, 114,</i> emporté par le vent jusqu’à terre ; <i>de maladies :</i> τοὺς δὲ λοιμὸς ὑπολαϐὼν ἀπήνεικε (<i>ion</i>.), HDT. <i>6, 27,</i> la peste les prit et les emporta ;<br><b>      2</b> rapporter, ramener, IL. <i>5, 257 ; au pass</i>. ἀπηνέχθη ἔτι ζῶν, XÉN. <i>Hell. 3, 3, 1,</i> il fut rapporté encore vivant ; <i>d’où, au pass.,</i> revenir, HDT. <i>4, 164, etc., en parl. de messages,</i> HDT. <i>1, 66, etc</i>. ATT. ; ἀποφέρειν μῦθόν τινι, IL. <i>10, 337,</i> rapporter une réponse à qqn ; τὰ ἀπενειχθέντα (<i>ion</i>.) HDT. <i>1, 66, 158, 160,</i> la réponse rapportée ;<br><b>      3</b> apporter en retour, payer <i>ou</i> acquitter (une dette, un tribut, <i>etc</i>.) HDT. <i>4, 35, etc</i>. THC. <i>5, 31 ;</i> PLAT. <i>Leg. 910</i> c ;<br><b>      4</b> déférer : γραφὴν πρός τινα, DÉM. <i>243, 11 ;</i> ESCHN. <i>56 fin,</i> déposer une accusation entre les mains d’un magistrat ; <i>p. ext</i>. formuler, rédiger : λόγον, DÉM. <i>819, 22,</i> un compte ; ἀπ. ἐν τῷ λόγῳ, DÉM. <i>1189, 8,</i> porter en compte ; ἀπ. ναύτας, DÉM. <i>1208, 6,</i> dresser une liste de matelots ;<br><b>   II <i>intr.</i></b> s’en aller : ἀπόφερ' ἐς κόρακας, AR. <i>Pax 1221,</i> va-t’en aux corbeaux, <i>càd</i>. au diable ! (<i>cf</i>. ἄπαγε) ;<br><b><i>Moy.</i></b> :<br><b>      1</b> emporter avec soi (<i>son bien, etc</i>.) HDT. <i>1, 132 ;</i> THC. <i>4, 97 ;</i><br><b>      2</b> remporter (un prix, une victoire, de la gloire, <i>etc</i>.) HDN <i>1, 5 ;</i> THCR. <i>Idyl. 1, 3 ;</i> A. PL. <i>166, etc. ; p. ext</i>. gagner, obtenir (une faveur, <i>etc</i>.) EUR. <i>El. 1089 ;</i><br><b>      3</b> emporter, EUR. <i>Ph. 1161</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. fut. dor</i>. ἀποισῶ, AR. <i>Ach. 779. Ao.1,</i> ἀπήνεγκα, THC. <i>5, 10. Ao.2</i> ἀπήνεγκον, AR. <i>Ach. 582, etc. Pf</i>. ἀπενήνοχα, DÉM. <i>819, 22. Pass. ao</i>. ἀπηνέχθην, XÉN. DÉM. <i>etc. ll. cc. Part. pf</i>. ἀπενηγμένος, DÉM. <i>1144, 14. Moy. fut</i>. ἀποίσομαι, LUC. <i>Bis acc. 33. Ao. act. pass. et moy. ion</i>. ἀπήνεικα, ἀπηνείχθην, ἀπηνεικάμην, HDT. <i>ll. cc. etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-φερω - ἀποφέρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G668":"<h1>apopheugo</h1>\n<p>Strong n° 668 <i>Prononciation [ap-of-yoo'-go]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>s'enfuir, s'échapper, se soustraire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·φεύγω</b> <span>(<i>f</i>. -φεύξομαι, <i>etc</i>.)</span><br><b>   I</b> échapper à, se soustraire à : τινά <i>ou</i> τι, BATR. <i>42 et 47 ;</i> HDT. <i>1, 1, etc</i>. ATT. à qqn <i>ou</i> à qqe ch. (<i>mort, maladie, danger, etc</i>.) ; <i>rar. avec le gén</i>. τῆς φθορᾶς, NT. échapper à la ruine ; ἐκ τόπου, XÉN. <i>An. 3, 4, 9,</i> s’échapper d’un lieu ; <i>abs</i>. sortir sain et sauf, HDT. <i>9, 102 ;</i><br><b>   II</b> <i>particul. :</i><br><b>      1</b> <i>t. de droit :</i> ἀπ. τοὺς διώκοντας, HDT. <i>6, 82 ;</i> δίκην, AR. <i>Nub. 167, ou</i> γραφήν, ANT. <i>115, 25,</i> se tirer d’une poursuite judiciaire, d’un procès, <i>càd</i>. être acquitté ; <i>avec deux acc</i>. ἀπ. τινὰ τὰς δίκας, DÉM. <i>1014, 8,</i> échapper à une poursuite intentée par qqn ; <i>abs</i>. être acquitté, HDT. <i>2, 174 ;</i> ATT. ;<br><b>      2</b> être délivrée par accouchement <i>ou</i> par avortement, MÉD.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. poét</i>. ἀποφευξοῦμαι, AR. <i>Av. 932 ; pf</i>. ἀποπέφευγα, XÉN. <i>An. 3, 4, 9, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-φευγω - ἀποφεύγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (3)</li>\n</ul>\n</td></tr>\n</table>","G669":"<h1>apophtheggomai</h1>\n<p>Strong n° 669 <i>Prononciation [ap-of-theng'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>parler, prononcer, s'exprimer, proférer, proclamer (sous l'inspiration de Dieu)\n<ol type=\"a\">\n<li>pas avec des paroles ordinaires, mais de celles « destinées à élever, à édifier »</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·φθέγγομαι :<br>      1</b> déclarer hautement LUC. <i>Zeux. 1 ; particul</i>. énoncer une sentence, PLUT. <i>M. 405</i> d ; rendre un oracle, LUC. <i>Alex. 25 ;</i><br><b>      2</b> rendre un son : ἀπ. σαθρόν, LUC. <i>Par. 4,</i> sonner le fêlé, <i>en parl. d’un vase ;</i><br><b>      3</b> chanter des hymnes, SPT. <i>1Par. 25, 1</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-φθεγγομαι - ἀποφθέγγομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G670":"<h1>apophortizomai</h1>\n<p>Strong n° 670 <i>Prononciation [ap-of-or-tid'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>poser une charge, décharger, délester\n<ol type=\"a\">\n<li>pour des marins délestant un navire dans la tempête pour éviter un naufrage</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·φορτίζομαι</b>, se décharger de, <i>acc</i>. ATH. <i>37</i> c, <i>etc. ; abs</i>. se soulager l’estomac <i>ou</i> le ventre, ARTÉM. <i>2, 26</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αποφορτιζομαι - ἀποφορτίζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G671":"<h1>apochresis</h1>\n<p>Strong n° 671 <i>Prononciation [ap-okh'-ray-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>abus, faire mauvais usage, maltraiter, action de méduser</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπόχρησις, εως (ἡ) :<br>      1</b> action de se défaire de, PLUT. <i>M. 267</i> f ;<br><b>      2</b> usage modéré, <i>càd</i>. action de se contenter de, DH. <i>1, 58 ;</i><br><b>      3</b> action de mésuser, NT.<br><span><b>Étym</b>. ἀποχράομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-χρησις - ἀπόχρησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G672":"<h1>apochoreo</h1>\n<p>Strong n° 672 <i>Prononciation [ap-okh-o-reh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>partir, se retirer, s'éloigner</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·χωρέω-ῶ :<br>   I</b> <i>avec mouv. :</i><br><b>      1</b> s’éloigner : δόμων, AR. <i>Ach. 456,</i> de chez moi ; ἀπὸ <i>ou</i> ἐκ τόπου, ATT. d’un lieu ; <i>en parl. d’une armée,</i> se replier, battre en retraite, THC. <i>2, 89 ;</i> ἐπὶ τόπου, THC. <i>2, 94,</i> vers un lieu ; <i>fig</i>. recourir : εἴς τι, DÉM. <i>793, 14 ;</i> ἐπί τι, <i>772, 26,</i> à qqe ch. ;<br><b>      2</b> se séparer, <i>d’où</i> être évacué par les selles, HPC. <i>53, 1, etc. ;</i> XÉN. <i>Cyr. 1, 2, 16 ;</i> τὰ ἀποχωροῦντα, XÉN. <i>Mem. 1, 4, 6 ;</i> τὸ ἀποχωροῦν, ARSTT. <i>G.A. 1, 18, 53,</i> les excréments ;<br><b>   II</b> <i>sans mouv. en parl. d’un lieu,</i> être distant, éloigné, POL. <i>15, 27, 8</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-χωρεω - ἀποχωρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G673":"<h1>apochorizo</h1>\n<p>Strong n° 673 <i>Prononciation [ap-okh-o-rid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se séparer, couper</li>\n<li>partager en morceaux</li>\n<li>se séparer de, s'éloigner de</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·χωρίζω</b> <span>(<i>f</i>. ίσω, <i>att</i>. ιῶ)</span> séparer : τι ἀπό τινος, PLAT. <i>Soph. 226</i> d <i>ou</i> ἔκ τινος, PLAT. <i>Tim. 84</i> a, <i>ou</i> τινος, PLAT. <i>Tim. 59</i> d, une chose d’une autre.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-χωριξω - ἀποχωρίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G674":"<h1>apopsucho</h1>\n<p>Strong n° 674 <i>Prononciation [ap-ops-oo'-kho]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>expirer</li>\n<li>s'évanouir, évanouissement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπο·ψύχω</b> <span>[ῡ]</span> <span>(<i>f</i>. ύξω, <i>ao. pass</i>. ἀπεψύχθην, <i>ao.2</i> ἀπεψύγην <span>[ῠ]</span>)</span><br><b>   I</b> exhaler : βίον, SOPH. <i>Aj. 1031 ;</i> πνεῦμα, ANTH. <i>12, 72,</i> rendre l’âme, exhaler son souffle ; <i>abs</i>. expirer, mourir, THC. <i>1, 134 ;</i> BION <i>1, 79, etc. ;</i><br><b>   II</b> exposer à l’air, <i>d’où :</i><br><b>      1</b> faire sécher, DIOSC. <i>5, 89 ;</i><br><b>      2</b> rafraîchir, refroidir, SOSIPATER (ATH. <i>378</i> f) ; <i>au pass</i>. se refroidir <i>ou</i> se rafraîchir, IL. <i>21, 561 ;</i> TH. <i>H.P. 4, 7, 3 ; fig</i>. ἀπεψυγμένος πρός τι, ARSTT. <i>Rhet. 2, 5, 14,</i> refroidi, <i>càd</i>. devenu indifférent pour qqe ch. ;<br><b>      3</b> <i>impers</i>. ἀποψύχει, PLAT. <i>Phædr. 242</i> a, le temps se rafraîchit ;<br><b><i>Moy.</i></b> <span>(<i>ao.2 pass</i>. ἀπεψύγην)</span><br><b>      1</b> expirer, mourir, ESCHL. <i>fr. 102 ;</i> ἀποψυχόμενος, ARR. <i>Epict. 4, 1, 115,</i> qui perd le souffle (d’inquiétude) ;<br><b>      2</b> rafraîchir, refroidir : ἱδρῶ ἀποψύχεσθαι, IL. <i>11, 621 ; 22, 2,</i> rafraîchir sa sueur, <i>càd</i>. se rafraîchir, se reposer ; <i>cf</i>. IL. <i>21, 561</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απο-ψυχω - ἀποψύχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G675":"<h1>Appios</h1>\n<p>Strong n° 675 <i>Prononciation [ap'-pee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Appius = « la place du marché, le forum d'Appius »\n<ol><li>ville d'Italie, à 60 km de Rome sur la voie Appienne</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἄππιος, ου (ὁ)</b> = <i>lat</i>. Appius, <i>n. d’h. romain,</i> PLUT. <i>Cic. 26, etc. ; plur</i>. οἱ Ἄππιοι, les Appius, PLUT. <i>Æmil. 38</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αππιος - Ἄππιος</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G676":"<h1>aprositos</h1>\n<p>Strong n° 676 <i>Prononciation [ap-ros'-ee-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qu'un homme ne peut approcher</li>\n<li>trop distant, inaccessible, inabordable</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀ·πρόσιτος, ος, ον</b> <span>[ῐ]</span> inabordable, inaccessible, <i>en parl. de choses (montagne, précipice, etc</i>.) POL. <i>3, 49, 7 ;</i> DS. <i>19, 96 ; fig</i>. PLUT. <i>Alc. 4, etc</i>.<br><span><b>Étym</b>. ἀ, πρόσειμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-προσιτος - ἀπρόσιτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G677":"<h1>aproskopos</h1>\n<p>Strong n° 677 <i>Prononciation [ap-ros'-kop-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>qui n'a rien à se reprocher, ne faisant pas trébucher, qui ne choque pas, qui ne scandalise pas\n<ol type=\"a\">\n<li>d'une route spacieuse</li>\n<li>métaph : ne poussant pas les autres au péché par le mode de vie</li>\n</ol>\n</li>\n<li>métaph : non disposé au péché, innocent, sans tache</li>\n<li>sans délit, non troublé par sa conscience, irréprochable</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n① <b>ἀ·πρόσκοπος, ος, ον :<br>      1</b> qui n’aperçoit pas <i>ou</i> ne voit pas clairement, ESCHL. <i>Eum. 105 ;</i><br><b>      2</b> non exploré (chemin) SPT. <i>Sir. 35, 21</i>.<br><span><b>Étym</b>. ἀ, προσκέπτομαι.</span><br><br>\n② <b>ἀ·πρόσκοπος, ος, ον :<br>      1</b> <i>intr</i>. qui ne se heurte pas, qui ne fait pas de faux pas, NT. <i>Ap. 24, 16 ;</i><br><b>      2</b> qui ne fait pas faire de faux pas, <i>càd</i>. qui ne provoque pas de scandale, NT. <i>1Cor. 10, 32 ; Phil. 1, 10</i>.<br><span><b>Étym</b>. ἀ, προσκόπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-προσκοπος - ἀπρόσκοπος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G678":"<h1>aprosopoleptos</h1>\n<p>Strong n° 678 <i>Prononciation [ap-ros-o-pol-ape'-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans acception, impartial, sans préférence, sans acception de personne</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπροσωπολήπτως</b> (variante orthographique de ἀπροσωπολήμπτως), <i>adv</i>., sans acception de personnes, NT. <i>1Petr. 1, 17</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-προσωπολημπτως - ἀπροσωπολήμπτως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G679":"<h1>aptaistos</h1>\n<p>Strong n° 679 <i>Prononciation [ap-tah'-ee-stos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans trébucher, se tenir ferme, exempt de chute, qui va sans faux pas</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄ·πταιστος, ος, ον :<br>      1</b> qui ne fait pas de faux pas, XÉN. <i>Eq. 1, 6 ; fig</i>. qui ne fait pas de fautes, infaillible, M. ANT. <i>5, 9 ; etc. ;</i><br><b>      2</b> où l’on ne fait pas de faux pas, PLUT. <i>M. 691</i> d.<br><span>•<i> Cp</i>. -ότερος, XÉN. <i>l. c</i>.<br><span><b>Étym</b>. ἀ, πταίω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-πταιστος - ἄπταιστος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G680":"<h1>haptomai</h1>\n<p>Strong n° 680 <i>Prononciation [hap'-tom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>s'attacher à, adhérer à, s'accrocher à\n<ol type=\"a\">\n<li>toucher</li>\n<li>relations charnelles avec une femme</li>\n<li>précepte lévitique de n'avoir aucune relation avec des habitudes païennes. Ce qu'il ne fallait pas toucher était à la fois les femmes et certains aliments, et donc le célibat et l'abstinence de nourriture et de boisson étaient recommandée.</li>\n<li>toucher, assaillir quelqu'un</li>\n</ol>\n</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>ἅπτω</b> <span>(<i>impf</i>. ἧπτον, <i>f</i>. ἅψω, <i>ao</i>. ἧψα, <i>pf. inus. ; pass. ao</i>. ἥφθην, <i>ao.2</i> ἥφην, <i>pf</i>. ἧμμαι)</span> ajuster, attacher, nouer : τι, OD. <i>21, 408,</i> qqe ch. ; βρόχῳ ἅ. δέρην, EUR. <i>Hel. 136, ou</i> βρόχους ἅ. κρεμαστούς, EUR. <i>Or. 1036,</i> attacher un lacet à son cou pour se pendre : ἅ. χορόν, ESCHL. <i>Eum. 307,</i> former (<i>litt</i>. nouer) un chœur de danse ; ἅ. πάλην τινί, ESCHL. <i>Ch. 868,</i> engager une lutte avec qqn ; <i>abs</i>. λύουσ' εἴθ' ἅπτουσα, SOPH. <i>Ant. 40,</i> déliant <i>ou</i> attachant, <i>càd</i>. quoi que je fasse, <i>sorte de proverbe ;</i><br><b><i>Moy</i>. ἅπτομαι</b> <span>(<i>impf</i>. ἡπτόμην, <i>f</i>. ἅψομαι, <i>ao</i>. ἡψάμην, <i>pf</i>. ἧμμαι)</span><br><b>   I</b> attacher pour soi : βρόχον ἀπὸ μελάθρου, OD. <i>11, 278,</i> un lacet au plafond (pour se pendre) ;<br><b>   II</b> toucher, <i>d’où :</i><br><b>      1</b> atteindre, <i>gén. :</i> ἀμφοτέρων βέλε' ἥπτετο, IL. <i>8, 67,</i> les traits les atteignirent tous deux ; ἅ. τῆς γῆς, DS. <i>4, 48,</i> toucher terre : <i>rar. avec le dat</i>. PD. <i>P. 10, 28 ; I. 3, 30 ; fig</i>. τῆς ἀληθείας, PLAT. <i>Phæd. 65</i> b, <i>etc</i>. parvenir à la vérité ; τοῦ τέλους, PLAT. <i>Conv. 211</i> b, toucher au but, atteindre le but ; <i>p. ext</i>. saisir par les sens <i>ou</i> par l’esprit, percevoir, SOPH. <i>O.C. 1550 ;</i> PLAT. <i>Phæd. 99</i> e ;<br><b>      2</b> toucher, se mettre en contact avec, <i>d’où</i> avoir des relations intimes avec, <i>gén</i>. EUR. <i>Ph. 953 ;</i> PLAT. <i>Rsp. 701</i> b, <i>etc. ;</i><br><b>      3</b> toucher pour prendre, <i>en parl. de nourriture :</i> ἅ. βρώμης, ποτῆτος, OD. <i>10, 379,</i> prendre de la nourriture, de la boisson ; ὅσα ὄρνεα καὶ τετράποδα ἀνθρώπων ἅπτεται, THC. <i>2, 50,</i> toutes les espèces d’oiseaux et de quadrupèdes qui se nourrissent de chair humaine ; <i>particul</i>. toucher en suppliant : ἅ. γούνων, IL. <i>1, 512, ou</i> γονάτων, PD. EUR. ; χειρῶν, IL. <i>10, 377 ;</i> γενείου, OD. <i>19, 473,</i> toucher les genoux, les mains, la barbe de qqn en suppliant ;<br><b>      4</b> <i>avec idée d’hostilité,</i> porter la main sur, s’attaquer à, τινος, ESCHL. <i>Ag. 1608 ;</i> SOPH. <i>O.C. 830 ;</i> PLAT. <i>Rsp. 465</i> b, <i>etc</i>. porter la main sur qqn ; τῶν ἀλλοτρίων, PLAT. <i>Rsp. 360</i> b, s’attaquer au bien d’autrui ; <i>d’où, en parl. de troupes, d’armées,</i> attaquer, XÉN. <i>Hell. 5, 4, 43, etc. ;</i> POL. <i>2, 34 ; fig</i>. πόνοι ἅπτονται τοῦ σώματος, XÉN. <i>Cyr. 1, 6, 25,</i> la fatigue envahit le corps ; <i>en parl. de maladies, de fléaux :</i> ἅ. τῶν ἀνθρώπων, THC. <i>2, 48,</i> s’attaquer aux hommes ; <i>cf</i>. THC. <i>2, 50 ;</i> SOPH. <i>Tr. 1009 ; de même</i> attaquer en paroles, par des reproches <i>ou</i> des injures, HDT. <i>5, 92, 3 ; sans idée de violence,</i> ἅ. τῶν λόγων, PLAT. <i>Phæd. 86</i> d, <i>Rsp. 497</i> e, s’attaquer aux arguments d’autrui, les discuter ;<br><b>      5</b> <i>fig</i>. mettre la main à, se mettre à, s’adonner à : ἔργου, XÉN. <i>Hell. 1, 4, 5 ;</i> πράγματος, DÉM. <i>564, 26 ;</i> πολέμου, THC. <i>5, 61,</i> s’attacher à une œuvre, à une affaire, à une guerre, <i>càd</i>. entreprendre une œuvre, <i>etc. ;</i> λόγων, EUR. <i>Ion 544 ;</i> PLAT. <i>Rsp. 539</i> a, nouer un entretien (<i>mais v. ci-dessus</i> 4, ἅ. τῶν λόγων) ; φιλοσοφίας, PLAT. <i>Phæd. 64</i> a, s’adonner à l’éloquence, à la philosophie ; <i>en mauv. part :</i> φόνου, EUR. <i>I.T. 381 ;</i> PLAT. <i>Phæd. 108</i> b ; ἀσεϐημάτων, POL. <i>7, 13,</i> commettre un meurtre, des actes d’impiété ; <i>abs</i>. se mettre à la besogne, AR. <i>Eccl. 582 ;</i><br><b>      6</b> <i>fig</i>. se rattacher à, être en rapport avec : τινος, PLAT. <i>Soph. 261</i> c, <i>Parm. 165</i> d, <i>etc</i>. avec qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Pass. ao.1 ion</i>. ἅφθην, HDT. <i>1, 19. Ao.2 subj. 3 sg</i>. ἁφῇ, ARSTT. <i>H.A. 8, 4, 8 ; inf</i>. ἁφῆναι, D. CHR. <i>36, p. 93 Reiske. Pf. ion</i>. ἇμμαι, HDT. <i>1, 86. — Moy. impf. ion</i>. ἁπτόμην, IL. <i>2, 171 (vulg</i>.) HDT. <i>3, 137 ; 6, 70. Ao. ion</i>. ἁψάμην, IL. <i>10, 377 ; 23, 666 ;</i> SIM. AM. <i>fr. 1, 18 ;</i> HDT. <i>1, 19</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *h₂ep-, joindre, approprier ; <i>cf</i>. ἁφή, <i>lat</i>. aptus ; <i>l’aspiration initiale étant second., d’après</i> R. *sep-, <i>v</i>. ἕπω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απ-τομαι - ἅπτομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n36 fois dans 33 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (11)</li>\n<li>Luc (11)</li>\n<li>Jean (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G681":"<h1>hapto</h1>\n<p>Strong n° 681 <i>Prononciation [hap'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>attacher à, adhérer à\n<ol type=\"a\">\n<li>mettre le feu à une chose, allumer un feu ou une lampe</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n① <b>ἅπτω</b> <span>(<i>impf</i>. ἧπτον, <i>f</i>. ἅψω, <i>ao</i>. ἧψα, <i>pf. inus. ; pass. ao</i>. ἥφθην, <i>ao.2</i> ἥφην, <i>pf</i>. ἧμμαι)</span> ajuster, attacher, nouer : τι, OD. <i>21, 408,</i> qqe ch. ; βρόχῳ ἅ. δέρην, EUR. <i>Hel. 136, ou</i> βρόχους ἅ. κρεμαστούς, EUR. <i>Or. 1036,</i> attacher un lacet à son cou pour se pendre : ἅ. χορόν, ESCHL. <i>Eum. 307,</i> former (<i>litt</i>. nouer) un chœur de danse ; ἅ. πάλην τινί, ESCHL. <i>Ch. 868,</i> engager une lutte avec qqn ; <i>abs</i>. λύουσ' εἴθ' ἅπτουσα, SOPH. <i>Ant. 40,</i> déliant <i>ou</i> attachant, <i>càd</i>. quoi que je fasse, <i>sorte de proverbe ;</i><br><b><i>Moy</i>. ἅπτομαι</b> <span>(<i>impf</i>. ἡπτόμην, <i>f</i>. ἅψομαι, <i>ao</i>. ἡψάμην, <i>pf</i>. ἧμμαι)</span><br><b>   I</b> attacher pour soi : βρόχον ἀπὸ μελάθρου, OD. <i>11, 278,</i> un lacet au plafond (pour se pendre) ;<br><b>   II</b> toucher, <i>d’où :</i><br><b>      1</b> atteindre, <i>gén. :</i> ἀμφοτέρων βέλε' ἥπτετο, IL. <i>8, 67,</i> les traits les atteignirent tous deux ; ἅ. τῆς γῆς, DS. <i>4, 48,</i> toucher terre : <i>rar. avec le dat</i>. PD. <i>P. 10, 28 ; I. 3, 30 ; fig</i>. τῆς ἀληθείας, PLAT. <i>Phæd. 65</i> b, <i>etc</i>. parvenir à la vérité ; τοῦ τέλους, PLAT. <i>Conv. 211</i> b, toucher au but, atteindre le but ; <i>p. ext</i>. saisir par les sens <i>ou</i> par l’esprit, percevoir, SOPH. <i>O.C. 1550 ;</i> PLAT. <i>Phæd. 99</i> e ;<br><b>      2</b> toucher, se mettre en contact avec, <i>d’où</i> avoir des relations intimes avec, <i>gén</i>. EUR. <i>Ph. 953 ;</i> PLAT. <i>Rsp. 701</i> b, <i>etc. ;</i><br><b>      3</b> toucher pour prendre, <i>en parl. de nourriture :</i> ἅ. βρώμης, ποτῆτος, OD. <i>10, 379,</i> prendre de la nourriture, de la boisson ; ὅσα ὄρνεα καὶ τετράποδα ἀνθρώπων ἅπτεται, THC. <i>2, 50,</i> toutes les espèces d’oiseaux et de quadrupèdes qui se nourrissent de chair humaine ; <i>particul</i>. toucher en suppliant : ἅ. γούνων, IL. <i>1, 512, ou</i> γονάτων, PD. EUR. ; χειρῶν, IL. <i>10, 377 ;</i> γενείου, OD. <i>19, 473,</i> toucher les genoux, les mains, la barbe de qqn en suppliant ;<br><b>      4</b> <i>avec idée d’hostilité,</i> porter la main sur, s’attaquer à, τινος, ESCHL. <i>Ag. 1608 ;</i> SOPH. <i>O.C. 830 ;</i> PLAT. <i>Rsp. 465</i> b, <i>etc</i>. porter la main sur qqn ; τῶν ἀλλοτρίων, PLAT. <i>Rsp. 360</i> b, s’attaquer au bien d’autrui ; <i>d’où, en parl. de troupes, d’armées,</i> attaquer, XÉN. <i>Hell. 5, 4, 43, etc. ;</i> POL. <i>2, 34 ; fig</i>. πόνοι ἅπτονται τοῦ σώματος, XÉN. <i>Cyr. 1, 6, 25,</i> la fatigue envahit le corps ; <i>en parl. de maladies, de fléaux :</i> ἅ. τῶν ἀνθρώπων, THC. <i>2, 48,</i> s’attaquer aux hommes ; <i>cf</i>. THC. <i>2, 50 ;</i> SOPH. <i>Tr. 1009 ; de même</i> attaquer en paroles, par des reproches <i>ou</i> des injures, HDT. <i>5, 92, 3 ; sans idée de violence,</i> ἅ. τῶν λόγων, PLAT. <i>Phæd. 86</i> d, <i>Rsp. 497</i> e, s’attaquer aux arguments d’autrui, les discuter ;<br><b>      5</b> <i>fig</i>. mettre la main à, se mettre à, s’adonner à : ἔργου, XÉN. <i>Hell. 1, 4, 5 ;</i> πράγματος, DÉM. <i>564, 26 ;</i> πολέμου, THC. <i>5, 61,</i> s’attacher à une œuvre, à une affaire, à une guerre, <i>càd</i>. entreprendre une œuvre, <i>etc. ;</i> λόγων, EUR. <i>Ion 544 ;</i> PLAT. <i>Rsp. 539</i> a, nouer un entretien (<i>mais v. ci-dessus</i> 4, ἅ. τῶν λόγων) ; φιλοσοφίας, PLAT. <i>Phæd. 64</i> a, s’adonner à l’éloquence, à la philosophie ; <i>en mauv. part :</i> φόνου, EUR. <i>I.T. 381 ;</i> PLAT. <i>Phæd. 108</i> b ; ἀσεϐημάτων, POL. <i>7, 13,</i> commettre un meurtre, des actes d’impiété ; <i>abs</i>. se mettre à la besogne, AR. <i>Eccl. 582 ;</i><br><b>      6</b> <i>fig</i>. se rattacher à, être en rapport avec : τινος, PLAT. <i>Soph. 261</i> c, <i>Parm. 165</i> d, <i>etc</i>. avec qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Pass. ao.1 ion</i>. ἅφθην, HDT. <i>1, 19. Ao.2 subj. 3 sg</i>. ἁφῇ, ARSTT. <i>H.A. 8, 4, 8 ; inf</i>. ἁφῆναι, D. CHR. <i>36, p. 93 Reiske. Pf. ion</i>. ἇμμαι, HDT. <i>1, 86. — Moy. impf. ion</i>. ἁπτόμην, IL. <i>2, 171 (vulg</i>.) HDT. <i>3, 137 ; 6, 70. Ao. ion</i>. ἁψάμην, IL. <i>10, 377 ; 23, 666 ;</i> SIM. AM. <i>fr. 1, 18 ;</i> HDT. <i>1, 19</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *h₂ep-, joindre, approprier ; <i>cf</i>. ἁφή, <i>lat</i>. aptus ; <i>l’aspiration initiale étant second., d’après</i> R. *sep-, <i>v</i>. ἕπω.</span><br><br>\n② <b>ἅπτω</b> <span>(<i>impf</i>. ἧπτον, <i>f</i>. ἅψω, <i>ao</i>. ἧψα, <i>pf. inus. ; pass. ao</i>. ἥφθην, <i>pf</i>. ἧμμαι)</span> allumer : πεύκας, EUR. <i>Or. 1543 ;</i> λύχνον, AR. <i>Nub. 18, etc</i>. allumer des torches de résine, une lampe ; <i>fig</i>. πυρσὸν ὕμνων, PD. <i>I. 3, 61,</i> faire brûler un flambeau d’hymnes ; <i>au pass</i>. δᾷς ἡμμένη, AR. <i>Nub. 1490,</i> flambeau allumé ; ἄνθρακες ἡμμένοι, THC. <i>4, 100,</i> charbons embrasés ;<br><b><i>Moy.</i></b> (<i>inf. f</i>. ἅψεσθαι) s’allumer, OD. <i>9, 379</i>.<br><span><b>Étym</b>. <i>v</i>. ἅπτω¹.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απτω - ἅπτω</font>\n<br><br>mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (4)</li>\n</ul>\n</td></tr>\n</table>","G682":"<h1>Apphia</h1>\n<p>Strong n° 682 <i>Prononciation [ap-fee'-a]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Apphia = « fructueux », « qui porte du fruit »\n<ol><li>un Chrétien, membre de la maison de Philémon</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Απφια - Ἀπφία</font>\n<br><br>probablement origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philémon</li>\n</ul>\n</td></tr>\n</table>","G683":"<h1>apotheomai</h1>\n<p>Strong n° 683 <i>Prononciation [ap-o-theh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>repousser, pousser, jeter</li>\n<li>rejeter de soi, écarter\n<ol type=\"a\">\n<li>répudier, rejeter, refuser</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπ·ωθέω-ῶ</b> <span>(<i>f</i>. -ώσω, <i>ao</i>. ἀπέωσα, <i>etc</i>.)</span><br><b>      1</b> repousser : ὀχῆα, IL. <i>24, 446,</i> un verrou ; τινα οὐδοῦ, OD. <i>22, 76,</i> qqn du seuil (d’une maison) ; εἰς τοὔπισθεν, PLAT. <i>Soph. 261</i> b, rejeter en arrière ; ἐπάλξεις ἀπ. THC. <i>3, 23,</i> arracher des créneaux ;<br><b>      2</b> repousser au loin : ὀμίχλην, IL. <i>17, 649,</i> une vapeur ; τινα γῆς, SOPH. <i>O.R. 641, ou</i> ἐκ γῆς, HDT. <i>1, 173,</i> chasser qqn d’un pays ;<br><b>      3</b> pousser à la suite l’un de l’autre : σανίδας, HÉRON <i>Aut. 244,</i> les lames d’un plancher, <i>càd</i>. les ajuster, les assembler ;<br><b><i>Moy</i>. ἀπωθέομαι-οῦμαι</b> <span>(<i>f</i>. ἀπώσομαι, <i>etc</i>.)</span><br><b>      1</b> repousser <i>ou</i> écarter de soi : τινα, IL. <i>24, 508,</i> qqn ; τι, OD. <i>9, 305,</i> qqe ch. ; τινα ἐκ μεγάροιο, OD. <i>1, 270,</i> qqn d’un palais ; <i>en parl. d’ennemis, de dangers, etc</i>. Τρῶας, IL. <i>8, 206,</i> repousser, les Troyens ; νηῶν πῦρ, IL. <i>16, 301,</i> repousser des vaisseaux le feu de l’ennemi ; <i>fig</i>. repousser (le gain, la servitude, un traité, <i>etc</i>.) HDT. <i>1, 199 ;</i> THC. <i>5, 22 ;</i> PLAT. <i>Rsp. 366</i> a, <i>etc. ; abs</i>. refuser, SOPH. <i>Tr. 1249 ;</i><br><b>      2</b> repousser au loin : τινα, OD. <i>13, 276,</i> qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Act. fut. inf. épq</i>. ἀπωσέμεν, IL. <i>13, 367. Ao. poét</i>. ἄπωσα, IL. <i>24, 446, etc. ; d’où sbj. 1 pl. épq</i>. ἀπώσομεν, IL. <i>8, 96 ;</i> OD. <i>22, 76. — Pass. pf. inf</i>. ἀπεῶσθαι, THC. <i>2, 39 ; part. ion</i>. ἀπωσμένος, HDT. <i>5, 69. — Moy. fut. 2 sg. épq</i>. ἀπώσεαι, OD. <i>1, 270 ; fut. réc. avec augm</i>. ἀπεώσομαι <i>formé de l’ao</i>. ἀπέωσα, SPT. <i>4Reg. 21, 14. Ao. poét</i>. ἀπωσάμην, OD. <i>13, 276 ; ao. réc</i>. ἀπωθησάμην, DC. <i>38, 28</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απ-ωθεομαι - ἀπωθέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (3)</li>\n<li>Romains (2)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G684":"<h1>apoleia</h1>\n<p>Strong n° 684 <i>Prononciation [ap-o'-li-a]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>destruction, perdition\n<ol type=\"a\">\n<li>d'un navire</li>\n</ol>\n</li>\n<li>perte, ruine, destruction, dépense, gaspillage\n<ol type=\"a\">\n<li>d'argent, de biens</li>\n<li>la destruction qui consiste en misère éternelle en enfer</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀπώλεια, ας (ἡ) :<br>      1</b> destruction, ARSTT. <i>Nic. 4, 1, 5, etc. ;</i><br><b>      2</b> perte, perdition, POL. <i>6, 59 ;</i> NT. <i>Matth. 7, 13 ; Joh. 17, 12 ; Ap. 25, 16, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -είη, HPC. <i>1284, 44</i>.<br><span><b>Étym</b>. ἀπόλλυμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">απωλεια - ἀπώλεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n19 fois dans 18 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>Philippiens (2)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>2 Pierre (6)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G685":"<h1>ara</h1>\n<p>Strong n° 685 <i>Prononciation [ar-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une prière, une supplication</li>\n<li>une imprécation, un fléau, une malédiction, une prière de malédiction</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀρά, ᾶς (ἡ)</b> <span>[ᾰρ, <i>épq. à l’arsis</i> ᾱρ]</span><br><b>      1</b> prière, IL. <i>15, 378, etc. ;</i> HÉS. <i>O. 724 ;</i> PD. <i>I. 5, 40, etc</i>. ἀρὴν (<i>ion</i>.) ποιεῖσθαι, <i>avec une prop. inf</i>. HDT. <i>6, 63,</i> prier <i>ou</i> souhaiter que, <i>etc. ;</i><br><b>      2</b> <i>particul. en mauv. part,</i> imprécation, malédiction, <i>au pl</i>. IL. <i>9, 566 ;</i> ἀρὰς ἀρᾶσθαι, SOPH. <i>O.C. 952, ou</i> ἐπεύχεσθαί τινι, PLAT. <i>Criti. 119</i> e, prononcer des imprécations contre qqn ; l’Imprécation <i>personnifiée,</i> SOPH. <i>El. 111, O.R. 418 ; au pl</i>. Ἀραί, les Imprécations, ESCHL. <i>Eum. 417 ;</i><br><b>      3</b> <i>p. suite,</i> l’effet d’une malédiction, perte, ruine, IL. <i>12, 334, etc. ;</i> OD. <i>2, 59 ; en ce sens, plur</i>. Ἀραί, les divinités vengeresses, <i>chargées de l’accomplissement des imprécations, et confondues ainsi avec les Érinyes,</i> SOPH. <i>O.C. 1376,</i> Ἀρὰς καλοῦμαι, SOPH. <i>O.C. 1384,</i> j’invoque les divinités vengeresses, <i>càd</i>. je maudis.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἀρή, IL. <i>14, 485 ; 18, 100, etc. ;</i> OD. <i>2, 59, etc. Gén. pl. dissyll</i>. ἀρέων <span>[ᾱ]</span> IL. <i>9, 566 ; dat. pl. épq</i>. ἀρῇσιν, OD. <i>17, 496</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αρα - ἀρά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G686":"<h1>ara</h1>\n<p>Strong n° 686 <i>Prononciation [ar'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>donc, ainsi, en quoi, dans lequel ...</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄρα</b> <span>[ᾰᾰ]</span> <i>épq</i>. ἄρ <i>dev. une cons.,</i> ῥα <i>enclit. ;</i> ῥ' <i>dev. une voy.,</i> ῥά <i>dev. un digamma, particule toujours placée après un mot et marquant :</i><br><b>   I</b> <i>une simple transition (sens exclus. épq</i>.) puis, alors, et : στῆ δ' ἄρ' (ὄνειρος) IL. <i>2, 20,</i> et le songe se tint (au-dessus) ; <i>souv. employé après les particules copulatives</i> καί, τέ, δέ, HOM. ; <i>après les particules de temps :</i> τότε δή ῥα, τῆμος ἄρα, et alors ; ὅτε ῥα, ἐπεί ῥα, ἐπεὶ ἄρ, <i>etc</i>. puis lorsque, <i>etc</i>. HOM. ; <i>qqf. dans les deux propos. corresp. :</i> ὅτε δή ῥα… δή ῥα τότε, IL. <i>24, 31,</i> et lorsque… alors donc ; <i>après les adv. de temps :</i> αἶψα δ' ἄρα, αὐτίκα δ' ἄρ, <i>etc</i>. HOM. et aussitôt, alors tout à coup ; <i>dans une énumération,</i> IL. <i>2, 546, etc. ; après un part. marquant une idée de temps :</i> ὡς εἰπὼν κατ' ἄρ' ἕζετο, IL. <i>1, 68,</i> il parla ainsi, puis s’assit ; <i>cf</i>. OD. <i>1, 441, etc. ; abs</i>. πρός ῥα πλατάνιστον ὄρουσεν, IL. <i>2, 310,</i> alors il s’élança vers le platane ;<br><b>   II</b> <i>une conséquence,</i> par suite, ainsi donc, donc, <i>particul. :</i><br><b>      1</b> <i>pour marquer qu’un fait est la conséquence de ce qui vient d’être dit :</i> τοὔνεκ' ἄρ' ἄλγε' ἔδωκεν, IL. <i>1, 96,</i> à cause de cela donc, (Apollon) a suscité des fléaux ; ἐρωτώσης τῆς μητρὸς ἀπεκρίνατο ἄρα, XÉN. <i>Cyr. 1, 3, 2,</i> sa mère l’ayant interrogé, il répondit donc ;<br><b>      2</b> <i>en parl. d’une chose dite ou supposée connue, et que l’on rappelle ainsi par allusion ou en forme de conclusion :</i> ὣς ἄρα φωνήσας, OD. <i>16, 213,</i> ayant donc ainsi parlé ; υἱὸν Πριάμοιο… τόν ῥ' Ὀδυσεὺς βάλε, IL. <i>4, 501,</i> le fils de Priam, celui que frappa, comme on sait, Ulysse ; <i>avec certaines conjonctions ou particules :</i> αὐτὸς ἄρα, ἄρα δέ, ὅς ῥά τε, ὅς τ' ἄρα, ἄρα μέν, ἄρα καί, ἄρα δή, HOM. ensuite donc ; <i>avec un mot interr. :</i> τίς ἄρα ; IL. <i>3, 226, etc. ;</i> OD. <i>1, 346, etc</i>. ATT. qui donc ? τί ἄρα ; XÉN. <i>Mem. 1, 3, 11,</i> quoi donc ? πῶς ἄρα ; ATT. comment donc ? <i>avec une nég. :</i> οὐδ' ἄρα πως ἦν δαήμονα φῶτα γενέσθαι, IL. <i>23, 670,</i> par suite il était impossible que je fusse un mortel habile (en toutes choses) ; οὔτ' ἄρα… οὔτε, HOM. par suite ni… ni ; οὔτε… οὔτ' ἄρα, HOM. ni… ni par suite, ni de même ;<br><b>      3</b> <i>en parl. d’une chose qu’on affirme par suite de raisons exprimées ou non :</i> οὐκ ἄρα σοίγε πατὴρ ἦν Πηλεύς, IL. <i>16, 33,</i> ainsi donc Pélée n’était pas ton père ; οὐκ ἄρ' ἀγαθὸς τὰ πολιτικὰ Περικλῆς ἦν ἐκ τούτου τοῦ λόγου, PLAT. <i>Gorg. 516</i> d, ainsi donc, d’après ce raisonnement, Périclès n’était pas un homme d’État habile ; <i>cf</i>. SOPH. <i>Ph. 978, Aj. 367 ;</i> ταῦτ' ἄρα, ATT. c’est donc pour cela que ;<br><b>   III</b> <i>une explication,</i> puisque, à savoir, c’est-à-dire, en effet : ὑπερφίαλον ἔπος ἔκϐαλε· φῆ ῥ' ἀέκητι θεῶν φυγέειν, OD. <i>4, 504,</i> il a prononcé une parole arrogante, car il a dit qu’il échapperait malgré les dieux ; πειρήσομαι, οἵτινές εἰσιν, ἤ ῥ' οἵ γ' ὑϐρισταί, ἠὲ φιλόξεινοι, OD. <i>9, 175,</i> j’éprouverai ce qu’ils sont, (à savoir) des hommes arrogants ou hospitaliers ; <i>après une conj</i>. ἐρῶ ὡς ἄρα, PLAT. <i>Theæt. 152</i> d, je dirai donc que ; εἰ ἄρα, THC. <i>1, 27 ; ou</i> ἐὰν ἄρα, PLAT. <i>Gorg. 469</i> d ; ἢν ἄρα, THC. <i>1, 93,</i> XÉN. <i>Cyr. 6, 3, 13,</i> si en effet, <i>pour marquer un doute ;</i> εἰ μὴ ἄρα, HDT. <i>4, 32, etc. ;</i> XÉN. <i>Mem. 1, 2, 8, etc. ;</i> ἐὰν μὴ ἄρα, PLAT. <i>Prot. 355</i> b, à moins qu’en effet, à moins que par hasard ; <i>avec ironie,</i> XÉN. <i>Mem. 1, 2, 8 ;</i><br><b>   IV</b> <i>Rem. :</i><br><b>      1</b> ἄρα <i>est qqf. répété dans une même propos. :</i> ὡς ἄρα φωνήσας κατ' ἄρ' ἕζετο, OD. <i>16, 213,</i> ayant donc ainsi parlé, il alla ensuite s’asseoir (<i>le 1<sup>er</sup></i> ἄρα <i>résume ce qui vient d’être dit, le 2<sup>e</sup> marque une corrélation entre les faits exprimés) ; cf</i>. OD. <i>18, 110 ;</i><br><b>      2</b> ἄρα <i>se place qqf. entre une prép. et un subst. :</i> ἔς ῥα θρόνους ἕζοντο, OD. <i>4, 51,</i> ils s’assirent donc sur leurs sièges ; μετ' ἄρα δμῳῇσι ἧστο, IL. <i>6, 323,</i> elle était donc assise au milieu de ses servantes ;<br><b>      3</b> ἄρα <i>se joint qqf. par crase à une particule précédente :</i> τἄρα, μεντἄρα, οὐτἄρα, <i>p</i>. τοι, μέντοι, οὔτοι ἄρα, <i>ou même à un mot précédent :</i> δήξομἄρα, AR. <i>Ach. 325 ;</i> οἰμώξετἄρα, AR. <i>Th. 248,</i> οἰμωξἄρα, AR. <i>Pl. 876 ;</i> κλαυσἄρα, AR. <i>Pax 532, etc. p</i>. δήξομαι, οἰμώξετε, οἰμώξει, κλαύσει, <i>et</i> ἄρα.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *h₂(e)r-, ainsi ; <i>cf. p.-ê</i>. ἀραρίσκω, ἄρτι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αρα - ἄρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Particule</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n51 fois dans 51 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (2)</li>\n<li>Luc (6)</li>\n<li>Actes (6)</li>\n<li>Romains (11)</li>\n<li>1 Corinthiens (5)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (6)</li>\n<li>Ephésiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G687":"<h1>ara</h1>\n<p>Strong n° 687 <i>Prononciation [ar'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>interrogation en Grec, qui implique de l'anxiété ou de l'impatience de la part du questionneur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἆρα</b> <span>[ᾰᾰ]</span><br><b>   I</b> <i>particule interrogative pour marquer l’impatience, la crainte,</i> est-ce donc que ? est-ce donc ? :<br><b>      1</b> <i>avec une réponse affirmative ou négative :</i> ἆρα βέϐληκα δὶς ἐφεξῆς ; XÉN. <i>Cyr. 6, 4, 4,</i> ai-je bien lancé <i>ou</i> frappé deux fois de suite ? (<i>réponse :</i> oui) ; ἆρ' οἴεσθε ; DÉM. <i>934, 4,</i> pensez-vous donc ? (<i>réponse :</i> non) ; <i>au commenc. d’une prop. indir. :</i> σκεψώμεθα τοῦτο ἆρα, PLAT. <i>Phæd. 70</i> e, examinons si en effet ;<br><b>      2</b> ἆρ' οὐ ; ἆρ' οὐχί ; = <i>lat</i>. nonne, <i>avec réponse affirmative,</i> SOPH. <i>O.C. 791, etc. ;</i> PLAT. <i>Phæd. 64</i> c, <i>etc. ;</i> ἆρ' οὖν οὐ ; <i>ou simpl</i>. ἆρ' οὖν ; PLAT. <i>Gorg. 477</i> a, <i>ou seul</i>. ἆρα, SOPH. <i>Tr. 988, m. sign. ;</i><br><b>      3</b> ἆρα μή : = <i>lat</i>. num, <i>avec réponse négative,</i> ESCHL. <i>Sept. 208 ;</i> ἆρ' οὖν μή ; ATT. <i>m. sign. ;</i><br><b>   II</b> <i>équivalent de</i> ἄρα, donc :<br><b>      1</b> <i>après un mot interrog. :</i> τίς ἆρα ; τί δ' ἆρα ; SOPH. <i>Aj. 905 ;</i> EUR. <i>I.A. 1228 ;</i> AR. <i>Vesp. 893,</i> qui donc ? quoi donc ? <i>ou après</i> ἤν, EUR. <i>Rhes. 118,</i> si donc ;<br><b>      2</b> <i>abs</i>. τοιοῖσδε χρησμοῖς ἆρα χρὴ πεποιθέναι, ESCHL. <i>Ch. 297,</i> certes à de tels oracles il faut obéir ; <i>cf</i>. PD. <i>P. 4, 78 ;</i> AR. <i>Av. 91 ; particul. dans les exclamations,</i> SOPH. <i>Aj. 738 ;</i> EUR. <i>Ph. 575</i>.<br><span><b><span class=\"arrow\"></span></b> ἆρα <i>au sens du</i> § I <i>se construit d’ord. au commenc. de la propos. ; en poésie, et rar. en prose</i> (PLAT. <i>Phæd. 67</i> c), <i>il peut se placer après d’autres mots</i>.<br><span><b>Étym</b>. <i>contract. de</i> ἦ ἄρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αρα - ἆρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Particule</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G688":"<h1>Arabia</h1>\n<p>Strong n° 688 <i>Prononciation [ar-ab-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Arabie (Angl. Arabia) = « désert », « stérile »\n<ol><li>une péninsule bien connue d'Asie, vers l'Afrique, limitée par l'Egypte, la Palestine, la Syrie, la Mésopotamie, la Babylonie, le Golfe d'Arabie, le Golfe Persique, la Mer Rouge, et l'Océan Indien.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἀραϐία, ας (ἡ)</b> <span>[ᾰρᾰ]</span> Arabie, <i>contrée d’Asie,</i> ESCHL. <i>Pr. 420, etc</i>.<br><span>[ᾱρᾰ-]</span> DP. <i>925. Ion</i>. Ἀραϐίη, HDT. <i>2, 8, 12, etc. ;</i> LUC. <i>Syr. 30 ;</i> ARR. <i>Ind. 32, 7, 43 ;</i> DP. <i>925. Poét</i>. Ἀρραϐία, THCR. <i>Idyl. 17, 86 ;</i> NONN. <i>D. 17, 392, etc</i>.<br><span><b>Étym</b>. Ἄραψ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αραβια</font> &lt; ערב - <font face=\"Georgia\">Ἀραβία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Galates (2)</li>\n</ul>\n</td></tr>\n</table>","G689":"<h1>Aram</h1>\n<p>Strong n° 689 <i>Prononciation [ar-am']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Aram (ou Ram) = « haut », « élevé », « exalté »\n<ol><li>un ancêtre de Christ</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αραμ</font> &lt; רם - <font face=\"Georgia\">Ἀράμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G690":"<h1>Araps</h1>\n<p>Strong n° 690 <i>Prononciation [ar'-aps]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un Arabe</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἄραψ, αϐος (ὁ)</b> <span>[ᾰᾰϐ]</span> d’Arabie, arabe, NONN. <i>D. 36, 326, etc. ;</i> οἱ Ἄραϐες, les Arabes, NONN. <i>D. 26, 23, etc</i>.<br><i>Dat. pl</i>. Ἄραψι ; <i>poét</i>. Ἀράϐεσσι, NONN. <i>D. 26, 23 ; 39, 18</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αραψ - Ἄραψ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G691":"<h1>argeo</h1>\n<p>Strong n° 691 <i>Prononciation [arg-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être désœuvré, inactif, s'attarder, retarder, être sans effet</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀργέω-ῶ</b>, <i>contr. de</i> ἀεργέω :<br><b>      1</b> ne pas travailler, ne rien faire, <i>en parl. de pers</i>. PLAT. <i>Rsp. 426</i> a ; DÉM. <i>38, 19, etc. ; en parl. du corps restant inactif,</i> HPC. <i>854</i> c ; <i>en parl. de choses :</i> γῆ ἀργοῦσα, XÉN. <i>Cyr. 1, 6, 11,</i> terre inactive, en jachère ; ἀργεῖ τὸ ἐργαστήριον, DÉM. <i>819, 17,</i> l’atelier est inactif ; <i>avec un gén</i>. ἀ. τινος, PLAT. <i>Rsp. 371</i> c, se reposer de qqe occupation ; <i>au pass</i>. être négligé, être omis par négligence, XÉN. <i>Cyr. 2, 3, 3, etc. ;</i><br><b>      2</b> <i>postér</i>. être réduit à l’inaction, être suspendu de son ministère, <i>en parl. de prêtres,</i> ECCL.<br><span><b>Étym</b>. ἀργός².</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αργεω - ἀργέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G692":"<h1>argos</h1>\n<p>Strong n° 692 <i>Prononciation [ar-gos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sans travail, avec loisirs</li>\n<li>paresseux, fuir le travail, inutile</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n① <b>ἀργός, ή, όν :<br>   I</b> brillant, <i>d’où :</i><br><b>      1</b> luisant, <i>en parl. d’une oie grasse,</i> OD. <i>15, 161 ; d’un bœuf fort et gras,</i> IL. <i>23, 30 ;</i><br><b>      2</b> blanc, ARSTT. <i>Top. 6, 11, 3 ;</i><br><b>   II</b> rapide, agile, léger, <i>à cause du rapport entre l’idée de lumière et celle de vitesse :</i> πόδας ἀργοί, IL. <i>18, 578 ;</i> OD. <i>2, 11, ou simpl</i>. ἀργοί, IL. <i>1, 50, etc</i>. aux pieds agiles (<i>cf</i>. ἀργίποδες) <i>en parl. de chiens</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *h₂rǵ-, blanc ; <i>cf. lat</i>. argentum ; <i>p. le développement du sens cf</i>. ἀργικέραυνος.</span><br><br>\n② <b>ἀργός, ός, όν</b>, <i>contract. de</i> ἄεργος,<br><b>   I</b> <i>intr. :</i><br><b>      1</b> qui ne fait pas, <i>gén</i>. ESCHL. <i>Sept. 411 ; abs</i>. qui ne travaille pas à la terre, HDT. <i>5, 6 ; en mauv. part,</i> paresseux, oisif, ATT. ; ἀ. τινος, EUR. <i>I.A. 1000,</i> n’ayant pas à s’occuper de qqe ch. ; ἀ. περί τι, PLAT. <i>Leg. 966</i> d ; πρός τι, PLUT. <i>M. 45</i> b, paresseux pour qqe ch. ;<br><b>      2</b> <i>en parl. de choses,</i> qui n’aboutit à rien : ἀ. δόρυ, EUR. <i>Ph. 1387,</i> lance qui ne blesse pas ; ἀ. χρήματα, DÉM. <i>815, 15,</i> argent qui ne rapporte rien, <i>p. opp. à</i> ἔνεργος ; ἀ. διατριϐή, AR. <i>Ran. 1498 ;</i> ISOCR. <i>49</i> c, exercice stérile ; νῆες ἀργότεραι ἐς τὸ δρᾶν τι, THC. <i>7, 67,</i> vaisseaux impuissants à faire qqe ch. ;<br><b>   II</b> <i>pass. :</i><br><b>      1</b> non travaillé : ἄργυρος ἀ. PAUS. <i>3, 12, 3,</i> argent brut ; λίθοι ἀργοί, pierres brutes (où se tenaient l’accusé et l’accusateur), EUR. <i>I.T. 962 ;</i> γῆς ἀ. XÉN. <i>Cyr. 3, 2, 19,</i> terre non cultivée ; σῖτος ἀ. ARSTT. <i>Ath. 51, 3</i> grain ; ἀ. μάχη, PLAT. <i>Euthyd. 272</i> a, lutte non pratiquée ;<br><b>      2</b> non fait, inachevé, négligé, THGN. <i>584 ;</i> οὐκ ἐν ἀργοῖς, SOPH. <i>O.R. 287,</i> qui n’est pas parmi les choses négligées ; <i>p. suite,</i> qui reste à faire, SOPH. <i>O.C. 1605 ;</i> EUR. <i>Ph. 767</i>.<br><span>•<i> Cp</i>. -ότερος, THC. <i>7, 67 ;</i> XÉN. <i>Cyr. 4, 3, 2 ;</i> PLAT. <i>Rsp. 458</i> a, <i>etc.</i> <i>• Sup</i>. -ότατος, XÉN. <i>Mem. 3, 13, 4 ;</i> ARSTT. <i>Pol. 1, 8 ; etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. ἀργή, ARSTT. <i>Nic. 9, 5, 3, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αργος - ἀργός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – désœuvré, impliquant une action blâmable, répréhensible\n<br><br> – lent, paresseux, faisant référence à un moment, et non nécessairement dans un mauvais sens\n<br><br> – paresseux, descriptif de qualités constitutionnelles, et suggérant une critique</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>1 Timothée (2)</li>\n<li>Tite (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G693":"<h1>argureos</h1>\n<p>Strong n° 693 <i>Prononciation [ar-goo'-reh-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>d'argent, argenté</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀργύρεος-οῦς, έα-ᾶ, εον-οῦν</b> <span>[ῠ]</span><br><b>      1</b> d’argent, IL. <i>1, 49, etc. ;</i> OD. <i>4, 615 ;</i> HÉS. <i>O. 143 ;</i> ATT. <i>etc. ;</i> ὁ ἀργυροῦς (<i>s.-e</i>. σίκλος) HÉRON, SPT. denier d’argent ;<br><b>      2</b> argenté, HDT. <i>9, 82</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Duel fém</i>. ἀργυρᾶ, <i>Inscr. att. (Rev. de phil. 5, 165). Trisyll</i>. ἀργυρέῳ, HÉS. <i>O. 143</i>.<br><span><b>Étym</b>. ἄργυρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αργυρεος - ἀργύρεος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>2 Timothée (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G694":"<h1>argurion</h1>\n<p>Strong n° 694 <i>Prononciation [ar-goo'-ree-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>argent (métal)</li>\n<li>de l'argent (monnaie)</li>\n<li>une pièce d'argent, un « shekel » (un sicle)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀργύριον, ου (τὸ)</b> <span>[ῠ]</span> pièce d’argent, XÉN. <i>Œc. 19, 16 ;</i> PLAT. <i>Leg. 742</i> d, <i>etc. ; d’où en gén</i>. argent monnayé, HDT. <i>3, 13 ;</i> THC. <i>2, 70 ;</i> XÉN. <i>Cyr. 3, 1, 33, etc</i>.<br><span><b>Étym</b>. ἄργυρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αργυριον - ἀργύριον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n20 fois dans 20 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n<li>Actes (5)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G695":"<h1>argurokopos</h1>\n<p>Strong n° 695 <i>Prononciation [ar-goo-rok-op'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un orfèvre</li>\n<li>dans le Temple d'Artémis, l'orfèvre fabriquait des réductions en argent du Temple d'Artémis</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀργυρο·κόπος, ου (ὁ)</b> <span>[ῠ]</span><br><b>      1</b> monnayeur, PHRYN. COM. <i>2-1, 582, 5 Mein. ;</i><br><b>      2</b> batteur d’argent, PLUT. <i>M. 830</i> e.<br><span><b>Étym</b>. ἄ. κόπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αργυρο-κοπος - ἀργυροκόπος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G696":"<h1>arguros</h1>\n<p>Strong n° 696 <i>Prononciation [ar'-goo-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>argent\n<ol type=\"a\">\n<li>Le verset <a class=\"ref\" data-r=\"1CO3.12\">1 Corinthiens 3.12</a> se réfère à l'argent qui recouvrait les colonnes des immeubles importants et qui décorait les poutres</li>\n<li>les choses faites en argent\n<ol>\n<li>vases, vaisselle</li>\n<li>images de dieux</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>argent (monnaie)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄργυρος, ου (ὁ)</b> <span>[ῠ]</span><br><b>      1</b> argent, <i>métal,</i> HOM. (IL. <i>2, 857, etc. ;</i> OD. <i>6, 232, etc.) etc. ;</i> ἄ. χυτός, ARSTT. <i>An. 1, 3, 11, etc. ;</i> TH. <i>Lap. 60,</i> vif-argent ;<br><b>      2</b> argent monnayé, ESCHL. <i>Suppl. 935 ;</i> SOPH. <i>Ant. 322, etc. ; réc. en prose,</i> ALCIPHR. <i>2, 3, etc. (en ce sens le mot class. est</i> ἀργύριον).<br><span><b>Étym</b>. <i>R. indo-europ</i>. *h₂erǵ-, blanc éclatant ; <i>cf</i>. ἀργός¹, <i>lat</i>. argentum, arguō, <i>litt</i>. « montrer clairement ».</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αργυρος - ἄργυρος</font>\n<br><br>vient de argos (brillant)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G697":"<h1>Areios Pagos</h1>\n<p>Strong n° 697 <i>Prononciation [ar'-i-os pag'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Aréopage (Angl. Areopagus) = « colline d'Arès »\n<ol><li>une hauteur rocheuse dans la cité d'Athènes, à l'ouest de l'Acropole</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἄρειος πάγος (ὁ) :<br>      1</b> la colline d’Arès, <i>càd</i>. la colline du meurtre, <i>à Athènes, ainsi appelée parce qu’on y avait établi le tribunal qui connaissait du meurtre</i> (<i>v</i>. Ἄρης, HDT. <i>8, 52</i>) ;<br><b>      2</b> <i>p. suite,</i> l’Aréopage, <i>tribunal qui siégeait sur cette colline,</i> DÉM. <i>505, 10 ;</i> ESCHN. <i>11, 42, etc. ; avec séparation des deux mots ;</i> πάγος δ' Ἄρειος, ESCHL. <i>Eum. 688 ;</i> πάγος τ' Ἄρειος, ESCHL. <i>Eum. 693, m. sign. ; au plur</i>. Ἀρείοις ἐν πάγοις, EUR. <i>I.T. 1470 ;</i> πάγοισιν ἐν Ἀρείοισιν, EUR. <i>Or. 1651,</i> dans l’Aréopage ; ἡ ἐν Ἀρείῳ πάγῳ βουλή, XÉN. <i>Mem. 3, 5, 20 ;</i> ARSTT. <i>Pol. 2, 12, 2, etc. ;</i> ἡ ἐξ Ἀρείου πάγου βουλή, PLAT. <i>Ax. 367</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Inscr. att</i>. Ἀρέου πάγου, <i>Mitt. 5, 323 (fin du 4<sup>e</sup> siècle av. J.C</i>.) ; CIA. <i>3, 716, 807 (époque impériale</i>) ; Ἄρηος πάγος, CIA. <i>3, 1917, 2 (époque impériale) etc. Ion</i>. Ἀρήϊος HDT. <i>l. c</i>.<br><span><b>Étym</b>. Ἄρειος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αρειος ου παγος - Ἄρειος πάγος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G698":"<h1>Areopagites</h1>\n<p>Strong n° 698 <i>Prononciation [ar-eh-op-ag-ee'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un membre de la cour de l'Aréopage, un Aréopagite</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἀρεοπαγίτης, ου (ὁ)</b> <span>[ᾰᾰῑ]</span> membre de l’Aréopage, aréopagite, ESCHN. <i>1, 81, etc. ;</i> DÉM. <i>59, 83, etc. ;</i> ARSTT. <i>Ath. 4, 4 ; cf</i>. Ἀρειοπαγίτης.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αρεοπαγιτης - Ἀρεοπαγίτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G699":"<h1>areskeia</h1>\n<p>Strong n° 699 <i>Prononciation [ar-es'-ki-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>désirant plaire, désirant satisfaire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀρέσκεια, ας (ἡ)</b> <span>[ᾰρ]</span> soins pour plaire, <i>d’ord</i>. complaisance excessive, obséquiosité, ARSTT. <i>Eud. 2, 3, 7, etc. ;</i> TH. <i>Char. 5 ;</i> POL. <i>6, 2, 12, etc. ; en b. part,</i> prévenances, bonne grâce, PHIL. <i>1, 34, etc</i>.<br><span><b>Étym</b>. ἀρεσκεύομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αρεσκεια - ἀρεσκεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>"};
